function cusPrompt(key,desc){const sh=CUS_SHEETS.find(x=>x.key===key);if(!sh)return'';const n=sh.c*sh.r,d=(desc||'').trim()||'the character shown in the attached reference image';
 return`Reference: the attached image shows the exact character – ${d}. Keep face, proportions, colors and outfit identical in every cell. Ignore the background of the reference.

Create a SPRITE SHEET for a 2D fighting game (Marvel vs. Capcom 2 style, hand-painted, crisp clean dark outlines, high detail – same character and rendering style as the reference, but sharper and more detailed).

LAYOUT: exactly ${sh.c} columns x ${sh.r} rows = ${n} equally sized cells, reading order left to right, top to bottom, with clear empty space between all cells. No numbers, no text, no labels, no grid lines, no borders.
BACKGROUND: one perfectly flat, solid pure green (#00FF00) across the entire image. No gradient, no floor, no ground shadow, no vignette.
CHARACTER: side view, facing RIGHT (3/4 view like in fighting games). In EVERY cell the character has the same scale (the neutral stance is about 65% of the cell height) and the lowest foot rests on the same invisible ground line near the bottom of the cell. The whole character including tail, hair, cape and glow effects stays completely inside its own cell and never touches the cell edge or a neighbouring cell.
CELL 1 = the neutral fight stance exactly like in the reference (it is only used to calibrate the size).
CELLS 2-${n}: ${CUS_PROMPT_CELLS[key]}

Output in the highest resolution available.`}

// ===== core/particles =====

const qn=n=>Math.max(1,Math.round(n*GFX.fx));   // Partikelmenge je Qualitätsstufe
// Feuerwerk-Parameter (1:1 aus Ghostwriter, Zeiten in Sekunden bzw. Frames bei 60 FPS, Distanzen in logischen Pixeln)
const FW={rise:[39,57],stars:210,radius:[.24,.36],jitter:.06,depth:.2,drag:1.9,gravity:190,life:[1.7,2.7],size:11,pool:2400};
const GOLDEN=Math.PI*(3-Math.sqrt(5));
// Rakete nach k Frames: schnell am Anfang, zum Scheitel langsamer, mit leichtem Wackeln
function fwPos(r,age){const k=Math.min(1,Math.max(0,age/r.rise)),e=1-Math.pow(1-k,2.2);return{x:r.x0+Math.sin(age*.2)*5*(1-k),y:r.y0-(r.y0-r.topY)*e,k}}
// Hex-Farbe -> Farbton (0..360); fast weiß/grau -> kühles Blau
function hexHue(c){let h=String(c||'').replace('#','');if(h.length===3)h=h.split('').map(x=>x+x).join('');if(!/^[0-9a-f]{6}$/i.test(h))return 200;
 const r=parseInt(h.slice(0,2),16)/255,g=parseInt(h.slice(2,4),16)/255,b=parseInt(h.slice(4,6),16)/255,mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn;if(d<.08)return 200;
 let t=mx===r?((g-b)/d)%6:mx===g?(b-r)/d+2:(r-g)/d+4;t*=60;return t<0?t+360:t}
const fwBucket=h=>Math.floor((((h%360)+360)%360)/10);
// 37 Sprites (36 Farbtöne + weiß), einmalig und erst beim ersten Zeichnen gebaut (läuft so auch ohne Browser in den Tests)
let FWATLAS=null;
function fwAtlas(){if(FWATLAS)return FWATLAS;FWATLAS=[];
 for(let i=0;i<37;i++){const c=document.createElement('canvas');c.width=c.height=64;const g=c.getContext('2d'),h=i*10+5,gr=g.createRadialGradient(32,32,0,32,32,32);
  if(i===36){gr.addColorStop(0,'hsla(0, 0%, 100%, 1)');gr.addColorStop(.12,'hsla(200, 70%, 96%, 0.95)');gr.addColorStop(.3,'hsla(220, 90%, 85%, 0.4)');gr.addColorStop(1,'hsla(220, 100%, 80%, 0)')}
  else{gr.addColorStop(0,`hsla(${h}, 100%, 92%, 1)`);gr.addColorStop(.12,`hsla(${h}, 100%, 80%, 0.95)`);gr.addColorStop(.3,`hsla(${h}, 100%, 62%, 0.45)`);gr.addColorStop(1,`hsla(${h}, 100%, 55%, 0)`)}
  g.fillStyle=gr;g.fillRect(0,0,64,64);FWATLAS.push(c)}
 return FWATLAS}
class ParticleSystem{
 constructor(){this.p=[];this.rings=[];this.fl=[];this.sl=[];this.sh=[];this.gl=[];this.sd=[];this.pw=[];this.mk=[];this.bt=[];this.rk=[];this.ff=[];this.ft=0;this.fs=Array.from({length:FW.pool},()=>({alive:false,x:0,y:0,vx:0,vy:0,z:0,age:0,life:0,r:1,cls:0,ph:0,sp:0,ho:0,white:false,h:200}));this.fn=0;this.onBoom=null}
 burst(x,y,o={}){const n=qn(o.count||12);
  for(let i=0;i<n;i++){const a=(o.angle!==undefined?o.angle:Math.random()*6.283)+(Math.random()-.5)*(o.spread!==undefined?o.spread:6.283);
   const s=(o.speed||6)*(.4+Math.random()*.9);const l=(o.life||24)*(.7+Math.random()*.5);
   this.p.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:l,max:l,size:o.size||3,color:o.color||'#fff',g:o.gravity!==undefined?o.gravity:.15,streak:o.streak!==undefined?o.streak:1})}}
 // Schnelle, helle Impact-Partikel (Treffer-Blitz)
 spark(x,y,color,count=8,speed=10){count=qn(count);for(let i=0;i<count;i++){
  const a=Math.random()*6.283,s=speed*(.4+Math.random()*1.2),l=(8+Math.random()*10)|0;
  this.p.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:l,max:l,size:1.5+Math.random()*2,color,g:.25,streak:.7,flash:true})}}
 // Sternförmige Explosion für Combos / Heavy-Hits
 starburst(x,y,color,count=16){count=qn(count);for(let i=0;i<count;i++){
  const a=(i/count)*6.283+Math.random()*.5,s=2+Math.random()*7,l=(16+Math.random()*24)|0;
  this.p.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:l,max:l,size:2.5,g:.04,streak:1.4,color})}}
 // Schwebenes Konfetti für Wins
 confetti(x,y,color,count=30){const cols=[color,'#ffffff','#ffd23f','#ff4a4a','#3fe0ff','#7dffc8'];
  for(let i=0;i<count;i++){const a=Math.random()*6.283,s=.8+Math.random()*3,l=(50+Math.random()*90)|0;
   this.p.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-.6,life:l,max:l,size:2.5+Math.random()*3.5,color:cols[i%cols.length],g:.025,streak:0,confetti:true})}}
 // Lichtblitz mit 4-Zacken-Stern (Impact-Flare)
 flare(x,y,color,size=60,life=10,rot=0){if(GFX.fx<.5&&size<150)return;this.fl.push({x,y,color,size,life,l0:life,rot})}
 // Klingen-/Schlagstreifen entlang der Schlagrichtung
 slash(x,y,color,ang,len=90,life=9,w=7){if(GFX.fx<.5&&len<150&&Math.random()>.5)return;this.sl.push({x,y,color,ang,len,life,l0:life,w})}
 // Flache Bodenwelle (Landung, Wandbruch, Knockdown)
 shock(x,y,color,max=140,life=20){this.sh.push({x,y,color,r:8,max,life,l0:life})}
 // ---- Glitzer: funkelnde 4-Zack-Sterne (Farben wechseln, flackern) ----
 glitter(x,y,o={}){if(this.gl.length>1000*GFX.fx)return;const n=qn(o.count||14),cols=o.colors||['#ffffff','#ffe27a','#7df9ff','#ff7ae6'];
  for(let i=0;i<n;i++){const a=(o.angle!==undefined?o.angle:Math.random()*6.283)+(Math.random()-.5)*(o.spread!==undefined?o.spread:6.283),s=(o.speed||6)*(o.exact?1:.25+Math.random()),l=(o.life||40)*(.6+Math.random()*.8);
   this.gl.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:l,max:l,size:(o.size||4)*(.5+Math.random()),col:cols[(Math.random()*cols.length)|0],rot:Math.random()*3,vr:(Math.random()-.5)*.3,g:o.gravity!==undefined?o.gravity:.12,ph:Math.random()*6.28,age:0})}}
 // Drehende Splitter/Konfetti-Plättchen (kippen beim Fallen = glitzern)
 shard(x,y,o={}){if(this.sd.length>500)return;const n=o.count||8,cols=o.colors||['#ffffff','#ffe27a','#7df9ff','#ff7ae6'];
  for(let i=0;i<n;i++){const a=(o.angle!==undefined?o.angle:Math.random()*6.283)+(Math.random()-.5)*(o.spread!==undefined?o.spread:6.283),s=(o.speed||6)*(.3+Math.random()),l=(o.life||50)*(.7+Math.random()*.6);
   this.sd.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:l,max:l,w:(o.w||5)*(.6+Math.random()),h:(o.h||10)*(.6+Math.random()),col:cols[(Math.random()*cols.length)|0],rot:Math.random()*6.283,vr:(Math.random()-.5)*.4,g:o.gravity!==undefined?o.gravity:.3,drag:o.drag||.985,ph:Math.random()*6.28,age:0})}}
 // Comic-Zackenstern (Treffer-Explosion) + Fadenkreuz-Hitmarker + Blitzbogen
 starpop(x,y,color,size=70,life=9){if(GFX.fx<.5&&size<150)return;this.pw.push({x,y,color,size,life,l0:life,rot:Math.random()*6.283,n:9+((Math.random()*5)|0),seed:Math.random()*100})}
 marker(x,y,color,size=40,life=11){this.mk.push({x,y,color,size,life,l0:life,rot:Math.PI/4+(Math.random()-.5)*.25})}
 bolt(x,y,color,ang,len=120,life=7){if(GFX.fx<.5||(GFX.fx<1&&Math.random()>.5))return;const pts=[[x,y]];let px=x,py=y,a=ang;const n=6;for(let i=0;i<n;i++){a+=(Math.random()-.5)*1.1;px+=Math.cos(a)*len/n;py+=Math.sin(a)*len/n;pts.push([px,py])}this.bt.push({pts,color,life,l0:life})}
 // Feuerwerk (aus Ghostwriter übernommen): Rakete steigt mit Schweif auf und platzt zu einer Kugel aus blinkenden Sternen.
 // x,y = Start, ty = Höhe der Explosion, color = Grundfarbe der Kugel (Hex)
 rocket(x,y,ty,color,sc=1){this.rk.push({sc,x0:x,y0:y,topY:ty,age:0,rise:FW.rise[0]+Math.random()*(FW.rise[1]-FW.rise[0]),h:hexHue(color),x:x,y:y})}
 _fwStar(){const p=this.fs[this.fn];this.fn=(this.fn+1)%this.fs.length;const roll=Math.random();
  p.cls=roll<.6?0:roll<.92?1:2;p.r=p.cls===0?.8+Math.random()*.4:p.cls===1?1.3+Math.random()*.7:2.2+Math.random()*.8;
  p.ph=Math.random()*6.2832;p.sp=2+Math.random()*6;p.ho=(Math.random()-.5)*50;p.white=Math.random()<.14;p.alive=true;p.age=0;p.z=0;return p}
 // Die Explosion: echte Kugel. Flugrichtungen gleichmäßig auf einer 3D-Kugel (Fibonacci-Spirale), sichtbar ist die Seitenansicht.
 boom(r){const R=(r.sc||1)*Math.min(W,H)*(FW.radius[0]+Math.random()*(FW.radius[1]-FW.radius[0])),off=Math.random()*6.2832;
  const NS=Math.max(40,Math.round(FW.stars*GFX.fireworks));for(let i=0;i<NS;i++){const p=this._fwStar(),z=1-(2*(i+.5))/NS+(Math.random()-.5)*.04,side=Math.sqrt(Math.max(0,1-z*z)),ang=off+i*GOLDEN,v=R*FW.drag*(1-Math.random()*FW.jitter);
   p.x=r.x;p.y=r.y;p.vx=Math.cos(ang)*side*v;p.vy=Math.sin(ang)*side*v;p.z=z;p.life=(FW.life[0]+Math.random()*(FW.life[1]-FW.life[0]))*(r.sc&&r.sc<1?.65:1);p.h=r.h}
  this.ff.push({x:r.x,y:r.y,age:0});if(this.onBoom)this.onBoom(r)}
 ring(x,y,color,max=60){this.rings.push({x,y,r:6,max,color,life:14,l0:14})}
 update(){for(const p of this.p){p.x+=p.vx;p.y+=p.vy;p.vy+=p.g;p.vx*=.96;p.life--}
  this.p=this.p.filter(p=>p.life>0);
  for(const r of this.rings){r.r+=(r.max-r.r)*.25;r.life--}this.rings=this.rings.filter(r=>r.life>0);
  for(const l of[this.fl,this.sl])for(const e of l)e.life--;this.fl=this.fl.filter(e=>e.life>0);this.sl=this.sl.filter(e=>e.life>0);
  for(const q of this.gl){q.x+=q.vx;q.y+=q.vy;q.vy+=q.g;q.vx*=.97;q.rot+=q.vr;q.life--;q.age++}this.gl=this.gl.filter(q=>q.life>0);
  for(const q of this.sd){q.x+=q.vx;q.y+=q.vy;q.vy+=q.g;q.vx*=q.drag;q.vy*=q.drag;q.rot+=q.vr;q.life--;q.age++}this.sd=this.sd.filter(q=>q.life>0);
  for(const l of[this.pw,this.mk,this.bt])for(const e of l)e.life--;this.pw=this.pw.filter(e=>e.life>0);this.mk=this.mk.filter(e=>e.life>0);this.bt=this.bt.filter(e=>e.life>0);
  this.ft++;const dt=1/60,now=this.ft/60;
  for(let i=this.rk.length-1;i>=0;i--){const r=this.rk[i];r.age++;const q=fwPos(r,r.age);r.x=q.x;r.y=q.y;
   if(q.k>=1){this.rk.splice(i,1);this.boom(r);continue}
   const p=this._fwStar();p.cls=0;p.r=.7+Math.random()*.4;p.x=q.x+(Math.random()-.5)*4;p.y=q.y+4;p.vx=(Math.random()-.5)*40;p.vy=30+Math.random()*60;p.life=.5+Math.random()*.4;p.h=r.h}
  const dec=Math.exp(-FW.drag*dt);
  for(const p of this.fs){if(!p.alive)continue;p.age+=dt;p.vy+=FW.gravity*dt;p.vx*=dec;p.vy*=dec;p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.age>p.life)p.alive=false}
  for(let i=this.ff.length-1;i>=0;i--){this.ff[i].age+=dt;if(this.ff[i].age>.4)this.ff.splice(i,1)}
  for(const r of this.sh){r.r+=(r.max-r.r)*.18;r.life--}this.sh=this.sh.filter(r=>r.life>0)}
 _drawFw(g){if(!this.rk.length&&!this.ff.length&&!this.fs.some(p=>p.alive))return;const A=fwAtlas(),T=this.ft/60;
  for(const f of this.ff){const k=f.age/.4,sz=220+260*k;g.globalAlpha=.55*(1-k)*(1-k);g.drawImage(A[36],f.x-sz/2,f.y-sz/2,sz,sz)}
  for(const r of this.rk){for(let j=0;j<6;j++){const q=fwPos(r,Math.max(0,r.age-j*1.56)),sz=20-j*2.2;g.globalAlpha=(1-j/6)*(j===0?1:.55);g.drawImage(A[36],q.x-sz/2,q.y-sz/2,sz,sz)}}
  for(const p of this.fs){if(!p.alive)continue;const s=.5+.5*Math.sin(T*p.sp+p.ph),tw=s*s*s,fade=Math.min(1,p.age/.05)*Math.min(1,(p.life-p.age)/.8),a=(.28+.72*tw)*fade;if(a<.01)continue;
   const hue=p.h+30+p.ho,sp=A[p.white?36:fwBucket(hue)],sz=p.r*FW.size*(.8+.5*tw)*(.65+.35*fade)*(1+FW.depth*p.z);
   g.globalAlpha=a;g.drawImage(sp,p.x-sz/2,p.y-sz/2,sz,sz);
   if(p.vx*p.vx+p.vy*p.vy>67600){g.globalAlpha=a*.35;g.drawImage(sp,p.x-p.vx*.018-sz/2,p.y-p.vy*.018-sz/2,sz,sz);g.globalAlpha=a*.16;g.drawImage(sp,p.x-p.vx*.036-sz/2,p.y-p.vy*.036-sz/2,sz,sz)}
   if(p.cls>=1&&tw>(p.cls===2?.55:.85)){const L=p.r*(3+6*tw)*(p.cls===2?1.6:1);g.globalAlpha=Math.min(1,a*.9);g.lineWidth=1;g.strokeStyle='hsla('+(((hue%360)+360)%360).toFixed(1)+', 100%, 90%, 1)';g.beginPath();g.moveTo(p.x-L,p.y);g.lineTo(p.x+L,p.y);g.moveTo(p.x,p.y-L);g.lineTo(p.x,p.y+L);
    if(p.cls===2){const d=L*.5;g.moveTo(p.x-d,p.y-d);g.lineTo(p.x+d,p.y+d);g.moveTo(p.x-d,p.y+d);g.lineTo(p.x+d,p.y-d)}g.stroke()}}
  g.globalAlpha=1}
 // Feuerwerk als eigene Ebene: Renderer zeichnet es hinter den Häusern (drawFw) und den Rest davor (draw(g,true)); Menü-Feuerwerk nutzt weiter draw(g)
 drawFw(g){g.save();g.globalCompositeOperation='lighter';this._drawFw(g);g.restore()}
 draw(g,noFw){g.save();g.globalCompositeOperation='lighter';g.lineCap='round';
  for(const p of this.p){const a=p.life/p.max;g.globalAlpha=a;g.strokeStyle=p.color;
   if(p.confetti){g.fillStyle=p.color;g.fillRect(p.x-1.5,p.y-1.5,p.size*a*2,p.size*a*2)}
   else{g.lineWidth=Math.max(.8,p.size*a);
    g.beginPath();g.moveTo(p.x,p.y);g.lineTo(p.x-p.vx*p.streak*1.6,p.y-p.vy*p.streak*1.6);g.stroke()}}
  for(const r of this.rings){g.globalAlpha=r.life/r.l0;g.strokeStyle=r.color;g.lineWidth=3*r.life/r.l0+1;g.beginPath();g.ellipse(r.x,r.y,r.r,r.r*.7,0,0,7);g.stroke()}
  for(const r of this.sh){const u=r.life/r.l0;g.globalAlpha=u*.9;g.strokeStyle=r.color;g.lineWidth=1+5*u;g.beginPath();g.ellipse(r.x,r.y,r.r,r.r*.16,0,0,7);g.stroke();g.globalAlpha=u*.5;g.strokeStyle='#fff';g.lineWidth=1+2*u;g.beginPath();g.ellipse(r.x,r.y,r.r*.96,r.r*.15,0,0,7);g.stroke()}
  for(const e of this.sl){const u=e.life/e.l0,L=e.len*(1.15-.35*u),w=e.w*u;g.save();g.translate(e.x,e.y);g.rotate(e.ang);
   for(const[c,k,a]of[[e.color,1,.75],['#ffffff',.42,.95]]){g.globalAlpha=a*u;g.fillStyle=c;g.beginPath();g.moveTo(-L/2,0);g.lineTo(0,-w*k);g.lineTo(L/2,0);g.lineTo(0,w*k);g.fill()}g.restore()}
  for(const e of this.fl){const u=e.life/e.l0,S=e.size*(.5+.7*(1-u)),gr=g.createRadialGradient(e.x,e.y,0,e.x,e.y,S);gr.addColorStop(0,'#ffffff');gr.addColorStop(.25,e.color);gr.addColorStop(1,'#0000');
   g.globalAlpha=u;g.fillStyle=gr;g.fillRect(e.x-S,e.y-S,S*2,S*2);g.save();g.translate(e.x,e.y);g.rotate(e.rot);g.fillStyle='#fff';g.globalAlpha=u*.9;
   for(let k=0;k<2;k++){g.rotate(k?1.5708:0);g.beginPath();g.moveTo(-S*1.5,0);g.lineTo(0,-S*.07);g.lineTo(S*1.5,0);g.lineTo(0,S*.07);g.fill()}g.restore()}
  const star=(x,y,sz,rot)=>{g.save();g.translate(x,y);g.rotate(rot);g.beginPath();g.moveTo(0,-sz);g.lineTo(sz*.17,-sz*.17);g.lineTo(sz,0);g.lineTo(sz*.17,sz*.17);g.lineTo(0,sz);g.lineTo(-sz*.17,sz*.17);g.lineTo(-sz,0);g.lineTo(-sz*.17,-sz*.17);g.closePath();g.fill();g.restore()};
  for(const q of this.sd){const u=q.life/q.max,fl=Math.abs(Math.cos(q.age*.35+q.ph));g.globalAlpha=Math.min(1,u*1.8)*(.5+.5*fl);g.fillStyle=q.col;g.save();g.translate(q.x,q.y);g.rotate(q.rot);g.fillRect(-q.w/2,-q.h*fl/2,q.w,Math.max(1,q.h*fl));g.restore()}
  for(const q of this.gl){const u=q.life/q.max,tw=.5+.5*Math.sin(q.age*.9+q.ph),a=Math.min(1,u*1.6)*(.45+.55*tw);g.globalAlpha=a;g.fillStyle=q.col;star(q.x,q.y,q.size*(.6+.4*u),q.rot);g.globalAlpha=a*.9;g.fillStyle='#fff';star(q.x,q.y,q.size*.42,q.rot)}
  for(const e of this.bt){const u=e.life/e.l0;for(const[c,w,a]of[[e.color,5,.55],['#ffffff',1.8,1]]){g.globalAlpha=a*u;g.strokeStyle=c;g.lineWidth=w;g.beginPath();e.pts.forEach((p,i)=>i?g.lineTo(p[0],p[1]):g.moveTo(p[0],p[1]));g.stroke()}}
  for(const e of this.pw){const u=e.life/e.l0,sc=.5+.5*Math.sqrt(1-u),n=e.n;for(const[k,c,a]of[[1,e.color,.9],[.55,'#ffffff',1]]){g.globalAlpha=Math.min(1,u*1.5)*a;g.fillStyle=c;g.beginPath();for(let i=0;i<n*2;i++){const r=e.size*sc*k*(i%2?.42:.78+.45*(Math.sin(e.seed+i*12.9)*.5+.5)),an=i*Math.PI/n+e.rot;i?g.lineTo(e.x+Math.cos(an)*r,e.y+Math.sin(an)*r):g.moveTo(e.x+Math.cos(an)*r,e.y+Math.sin(an)*r)}g.closePath();g.fill()}}
  for(const e of this.mk){const u=e.life/e.l0,L=e.size*(1+(1-u)*.5);g.save();g.translate(e.x,e.y);g.rotate(e.rot);g.lineCap='square';for(const[c,w,a]of[[e.color,3+u*7,.45],['#ffffff',1.5+u*3,1]]){g.globalAlpha=a*u;g.strokeStyle=c;g.lineWidth=w;g.beginPath();for(let k=0;k<4;k++){g.rotate(Math.PI/2);g.moveTo(L*.28,0);g.lineTo(L,0)}g.stroke()}g.restore()}
  if(!noFw)this._drawFw(g);
  g.restore()}
}

// ===== core/effects =====

// Fassade für Treffer-/Bewegungseffekte. Rendering-unabhängig: schreibt nur in das ParticleSystem.
const GLITTER_PAL=['#ffffff','#ffe27a','#7df9ff','#ff7ae6'];   // Glitzer-Farben neben der Figurenfarbe
class Effects{
 constructor(ps){this.ps=ps}
 hit(x,y,power,color,dir){const n=7+power*5,ps=this.ps,cols=[color,...GLITTER_PAL],fwd=dir>0?0:Math.PI;
  ps.burst(x,y,{count:n,speed:5+power*2.5,color:'#ffffff',life:14,size:2.4});
  ps.burst(x,y,{count:n,speed:4+power*2,color,life:26,size:3.2,angle:fwd,spread:2.4,gravity:.12});
  ps.ring(x,y,color,30+power*16);ps.ring(x,y,'#ffffff',18+power*10);
  ps.spark(x,y,color,6+power*4,9+power*2.5);
  // Hitmarker: Zackenstern + Fadenkreuz + Flare + Schlagstreifen
  ps.starpop(x,y,color,52+power*30,8+power);ps.marker(x,y,'#ffffff',36+power*18,11);
  ps.flare(x,y,color,48+power*30,9+power*3,Math.random());
  const a0=fwd+(Math.random()-.5)*.5;ps.slash(x,y,'#ffffff',a0,80+power*50,8+power,6+power*1.6);
  for(let i=0;i<power;i++)ps.slash(x,y,i%2?color:'#fff',a0+(i+1)*.42*(i%2?1:-1),60+power*34,10,4);
  // Glitzer + Splitter + Funken, Richtung Schlag und rundherum
  ps.glitter(x,y,{count:12+power*11,speed:5+power*2.4,life:42+power*12,size:3.6+power,colors:cols,gravity:.1,angle:fwd,spread:3.6});
  ps.glitter(x,y,{count:5+power*4,speed:2.4,life:70,size:3.2,colors:cols,gravity:-.012});
  if(power>=2){for(let i=0;i<2+power;i++)ps.bolt(x,y,i%2?color:'#7df9ff',Math.random()*6.283,90+power*34,6+((Math.random()*3)|0));
   ps.burst(x,y,{count:6+power*3,speed:6+power*2,color,life:44,size:2.6,angle:fwd,spread:2.2,gravity:.32})}
  if(power>=3)ps.shock(x,y+60,color,170,22)
 }
 block(x,y,color){const ps=this.ps;ps.burst(x,y,{count:9,speed:4.5,color,life:14,size:2.2,spread:3});ps.ring(x,y,'#9bd',24);ps.marker(x,y,'#8fd4ff',34,10);ps.starpop(x,y,'#8fd4ff',44,7);ps.glitter(x,y,{count:9,speed:5,life:34,size:3,colors:['#ffffff','#8fd4ff','#bfe9ff'],gravity:.08})}
 land(x,y,big){if(big)this.ps.shock(x,y,'#b9a8ff',120,18);
  this.ps.burst(x,y-2,{count:big?14:6,speed:big?5:2.5,color:'#8a7fb8',life:22,size:3,angle:-Math.PI/2,spread:3.4,gravity:-.01,streak:.4});if(big)this.ps.glitter(x,y-4,{count:10,speed:4,life:36,size:3,colors:['#ffffff','#b9a8ff'],angle:-Math.PI/2,spread:2.6})}
 jump(x,y){this.land(x,y,false)}
 dash(x,y,dir){this.ps.burst(x,y-8,{count:6,speed:3,color:'#9a8bff',life:16,size:2.4,angle:dir>0?Math.PI:0,spread:1.2,gravity:0});this.ps.glitter(x,y-8,{count:5,speed:3.4,life:32,size:2.8,colors:GLITTER_PAL,angle:dir>0?Math.PI:0,spread:1.4,gravity:.02})}
 // Combo-Effekt: skaliert mit der Trefferzahl, farbig nach Charakter
 combo(x,y,hits,color,dir){const n=10+hits*4,ps=this.ps,h=Math.min(hits,12);
  ps.burst(x,y,{count:n,speed:6+hits*2,color:'#ffffff',life:20,size:3});
  ps.starburst(x,y,color,12+hits*4);ps.ring(x,y,color,40+hits*20);ps.ring(x,y,'#ffffff',24+hits*12);
  ps.glitter(x,y,{count:8+h*4,speed:7+h*.8,life:50,size:4,colors:[color,...GLITTER_PAL]});
  if(hits>=4)ps.starpop(x,y,color,90+h*8,10);if(hits>=6)for(let i=0;i<4;i++)ps.bolt(x,y,color,Math.random()*6.283,140,8)
 }
 // Verstärkter K.O.: Explosion aus Licht, Glitzer, Splittern und Blitzen
 ko(x,y,color){const ps=this.ps,cols=[color,...GLITTER_PAL];
  ps.flare(x,y,'#ffffff',280,24,.3);ps.shock(x,y+80,color,440,36);for(let i=0;i<8;i++)ps.slash(x,y,i%2?color:'#fff',i*.7854+.2,260,16,10);
  ps.burst(x,y,{count:60,speed:14,color:'#ffffff',life:40,size:4});ps.burst(x,y,{count:30,speed:10,color,life:45,size:3.5,angle:0,spread:3});
  ps.starburst(x,y,color,24);ps.ring(x,y,color,220);ps.ring(x,y,'#ffffff',150);ps.ring(x,y,color,90);
  ps.starpop(x,y,color,230,14);ps.marker(x,y,'#ffffff',150,16);
  ps.glitter(x,y,{count:90,speed:13,life:80,size:6,colors:cols,gravity:.07});
  for(let i=0;i<10;i++)ps.bolt(x,y,i%2?color:'#7df9ff',i*.628+Math.random()*.4,200+Math.random()*120,8)
 }
 // Runden-Sieg, Auftakt: Lichtexplosion (der Dauer-Effekt kommt aus celebrate())
 win(x,y,color){const ps=this.ps,cols=[color,...GLITTER_PAL];
  ps.flare(x,y,'#ffffff',420,30,.1);ps.shock(x,GROUND,color,560,44);ps.shock(x,GROUND,'#ffffff',360,30);
  for(const r of[90,160,240])ps.ring(x,y,r%2?'#ffffff':color,r);
  ps.glitter(x,y,{count:130,speed:12,life:100,size:6.5,colors:cols,gravity:.05});
  for(let i=0;i<12;i++)ps.bolt(x,y,i*.5236,220+Math.random()*160,9);ps.starpop(x,y,color,260,16)
 }
 // Sieger-Finale: Lichtsäule (Renderer), Feuerwerk, Glitzerregen, aufsteigende Funken, Druckwellen. t = Frames seit Rundenende, cam = Kamera
 celebrate(f,t,cam){const ps=this.ps,col=f.char.glow||'#fff',cols=[col,'#ffd23f','#3fe0ff','#ff4fd8','#7dffc8'];
  if(t<240?t%32===2:t%90===2){const x=f.x+(Math.random()-.5)*620,ty=86+Math.random()*140;ps.rocket(x,GROUND,ty,cols[(Math.random()*cols.length)|0])}
  if(t%3===0)ps.glitter(f.x+(Math.random()-.5)*130,GROUND-4,{count:2,speed:2.6,life:90,size:3.4,colors:[col,'#ffe27a','#ffffff'],gravity:-.045,angle:-Math.PI/2,spread:.9});
  // Charakter-Aura (Renderer zeichnet die Flammen-/Blitzform): hier die passenden Partikel
  const sz=f.char.size||1;
  if(f.char.id==='tiger'){if(t%3===0)ps.bolt(f.x+(Math.random()-.5)*110,f.y-30-Math.random()*170*sz,Math.random()<.5?'#7df9ff':'#ffffff',Math.random()*6.283,60+Math.random()*80,6);if(t%5===0)ps.glitter(f.x,f.y-100,{count:5,speed:6,life:26,size:3,colors:['#ffffff','#7df9ff','#3fb8ff'],gravity:0})}
  else if(f.char.id==='mino'){if(t%2===0)ps.glitter(f.x+(Math.random()-.5)*150*sz,GROUND-6,{count:2,speed:3.2,life:70,size:4,colors:['#ff3a00','#ff8a1a','#ffc12e','#fff4c8'],gravity:-.06,angle:-Math.PI/2,spread:.7})}
  else if(t%4===0)ps.glitter(f.x+(Math.random()-.5)*100,GROUND-6,{count:2,speed:3,life:60,size:3.4,colors:[col,'#ffe9a8','#ffffff'],gravity:-.05,angle:-Math.PI/2,spread:.8});
  if(t%40===8){ps.ring(f.x,GROUND-10,col,300);ps.shock(f.x,GROUND,col,330,30);ps.glitter(f.x,f.y-100,{count:26,speed:9,life:60,size:4.4,colors:[col,...GLITTER_PAL],gravity:.04})}
 }
}

// ===== core/projectile =====


// Projektil. Felder der Definition (`proj`): frame (Spawn-Frame), ox/y (Versatz zum Kämpfer), vx/vy/grav (Bewegung, Bögen), w/h, dmg/hs/bs, life,
// pierce (n = durchschlägt, trifft alle n Frames erneut), uniq (nur 1 gleichzeitig, z. B. Falle), lv (Trefferhöhe), launch/hard, look (Darstellung)
class Projectile{
 constructor(owner,mv,d=mv.proj){this.owner=owner;this.def=d;this.x=owner.x+owner.facing*(d.ox||64);this.y=owner.y+d.y;
  this.vx=owner.facing*d.vx;this.vy=d.vy||0;this.grav=d.grav||0;this.life=d.life;this.dead=false;this.age=0;this.cd=0;this.w=d.w;this.h=d.h}
 update(){this.x+=this.vx;if(this.vy||this.grav){this.vy+=this.grav;this.y+=this.vy}
  if(this.cd>0)this.cd--;this.life--;this.age++;
  if(this.life<=0||this.x<WORLD.x0||this.x>WORLD.x1)this.dead=true;
  if(this.vy>0&&this.y>=GROUND-8)this.dead=true} // Bogen-/Schräg-Projektile verpuffen am Boden
 rect(){return new Hitbox(this.x-this.w/2,this.y-this.h/2,this.w,this.h)}
 // Projektile treffen wie Moves – gleiche Felder, damit combat.hit() nur einen Pfad braucht
 asMove(){const d=this.def;return{dmg:d.dmg,hs:d.hs,bs:d.bs,pb:4,pbb:5,hstop:8,shake:3,lv:d.lv||'mid',launch:d.launch||null,hard:!!d.hard,multi:0,minScale:0}}
}

// ===== core/fighter =====




const FACE_STATES=['idle','walk','crouch'];
const RANK={L:1,M:2,H:3};
let UID=0;
// Zustände: idle walk crouch air dash airdash attack hit block airhit tumble knockdown wakeup ko win
class Fighter{
 constructor({char,x,facing,input}){this.id=UID++;this.char=char;this.input=input;this.moves=buildMoves(char);
  this.maxHp=char.hp;this.startX=x;this.startFacing=facing;this.wins=0;this.meter=0;this.trail=[];this.comboShow={hits:0,dmg:0,t:0};this.reset()}
 reset(){Object.assign(this,{x:this.startX,y:GROUND,vx:0,vy:0,facing:this.startFacing,hp:this.maxHp,state:'idle',sf:0,mf:0,move:null,moveName:'',
  hitDone:false,contact:false,hitCd:0,stun:0,coyote:0,airJumps:this.maxAJ,airDashes:1,launched:false,chainLen:0,comboHits:0,comboDmg:0,juggle:0,hard:false,landLag:0,dashDir:0,
  noGrav:false,kdFrames:0,blockCrouch:false,anim:'idle',animU:0,_mo:0});this.trail.length=0;this.comboShow={hits:0,dmg:0,t:0}}
 // Kämpfer wechseln (Menü): neue Stats + Moves, danach Zurücksetzen
 setChar(char){this.char=char;this.moves=buildMoves(char);this.maxHp=char.hp;this.reset()}
 get grounded(){return this.y>=GROUND}
 get maxAJ(){const a=this.char.airJumps;return a===undefined?1:a} // Luft-Sprünge pro Luftphase (Figurenwert)
 // Schadensfaktor: Charakter-Wert x Schwierigkeits-Faktor der KI (falls die Eingabe eine KI ist)
 dmgMul(){return this.char.dmg*((this.input&&this.input.P&&this.input.P.dmg)||1)}
 setState(s){this.state=s;this.sf=0}
 // ---------- Boxen ----------
 hurtbox(){const s=this.state;let w=52,h=150;
  if(s==='knockdown'||(s==='ko'&&this.grounded)){w=140;h=38}
  else if(s==='crouch'||(s==='attack'&&this.move&&this.move.crouch)||(s==='block'&&this.blockCrouch))h=96;
  else if(!this.grounded)h=132;
  const z=this.char.size||1;w*=z;if(s!=='knockdown'&&!(s==='ko'&&this.grounded))h*=z;
  return new Hitbox(this.x-w/2,this.y-h,w,h)}
 activeHitbox(){const m=this.move;if(this.state!=='attack'||!m||!m.box)return null;
  if(this.mf<m.su||this.mf>=m.su+m.ac)return null;
  if(m.multi){if(this.hitCd>0)return null}else if(this.hitDone)return null;
  return{move:m,rect:Hitbox.fromBox(m.box,this)}}
 invulnerable(){const s=this.state;
  if(s==='knockdown'||s==='wakeup'||s==='win')return true;
  if(s==='attack'&&this.move&&this.move.inv&&this.mf>=this.move.inv[0]&&this.mf<=this.move.inv[1])return true;
  if(s==='dash'&&this.dashDir!==this.facing&&this.sf<6)return true;return false}
 isBlocking(m){const s=this.state;if(!['idle','walk','crouch','air','block'].includes(s))return false;
  if(s==='block')return true;
  if(this.input.dx*this.facing>=0)return false; // Zurückhalten = Block
  if(!this.grounded)return m.lv!=='low';
  const crouch=this.input.dy>0;
  if(m.lv==='low')return crouch;if(m.lv==='high')return !crouch;return true}
 // ---------- Frame-Update ----------
 update(opp,game){
  this.sf++;
  if(this.comboShow.t>0)this.comboShow.t--;
  if(this.comboFlash>0)this.comboFlash--;
  if(FACE_STATES.includes(this.state))this.facing=opp.x>=this.x?1:-1;
  if(this.grounded)this.coyote=PHYS.coyote;else if(this.coyote>0)this.coyote--;
  switch(this.state){
   case'attack':this.tickAttack(opp,game);break;
   case'hit':case'block':this.vx*=.84;if(--this.stun<=0){this.endCombo();this.blockCrouch=false;this.setState('idle')}break;
   case'airhit':if(--this.stun<=0){this.endCombo();this.airJumps=0;this.airDashes=0;this.setState('air')}break;
   case'knockdown':if(this.sf>=this.kdFrames)this.setState('wakeup');break;
   case'wakeup':if(this.sf>=18)this.setState('idle');break;
   case'dash':this.tickDash(game);break;
   case'airdash':this.tickAirDash(game);break;
   case'tumble':case'ko':case'win':break;
   default:this.free(game)}
  this.physics(game)}
 // ---------- Freie Aktionen ----------
 free(game){const i=this.input;
  if(this.landLag>0)this.landLag--;
  if(this.tryAttack(game))return;
  if(this.tryDash(game))return;
  this.tryJump(game);
  const dx=i.dx;
  if(!this.grounded){if(this.state!=='air')this.setState('air');this.vx+=(dx*PHYS.airDrift*this.char.walk-this.vx)*(dx?.18:.02);return}
  if(i.dy>0){if(this.state!=='crouch')this.setState('crouch');this.vx=0;return}
  if(dx){const rel=dx*this.facing;this.vx=dx*(rel>0?PHYS.walk:PHYS.back)*this.char.walk;if(this.state!=='walk')this.setState('walk')}
  else{this.vx=0;if(this.state!=='idle')this.setState('idle')}}
 // Sprung mit Jump-Buffering + Coyote-Time + Doppelsprung
 tryJump(game){const i=this.input,g=this.grounded;
  const want=i.pressed('UP',PHYS.jumpBuffer)||(i.dy<0&&g&&this.sf>1);
  if(!want)return false;
  if(g||this.coyote>0){i.consume('UP');this.vy=PHYS.jumpV*(this.char.jump||1);this.vx=i.dx*PHYS.walk*1.1*this.char.walk;this.y=Math.min(this.y,GROUND-1);
   this.coyote=0;this.airJumps=this.maxAJ;this.setState('air');game.fx.jump(this.x,GROUND);return true}
  if(this.airJumps>0&&i.pressed('UP',2)){i.consume('UP');this.vy=PHYS.airJumpV*(this.char.jump||1);this.vx=i.dx*PHYS.walk*1.1*this.char.walk;this.airJumps--;
   this.setState('air');game.fx.ps.ring(this.x,this.y-10,'#9a8bff',40);return true}
  return false}
 tryDash(game){const i=this.input;const dd=i.takeDash(),btn=i.pressed('DASH',3);if(!dd&&!btn)return false;if(btn)i.consume('DASH');
  const dir=dd||(i.dx||this.facing);
  if(this.grounded){this.dashDir=dir;this.vx=dir*PHYS.dash*(this.char.dash||1)*(dir===this.facing?1:.85);this.setState('dash');game.fx.dash(this.x,this.y,dir);game.sfx(dir===this.facing?'dash':'dodge',{rate:.72,vol:.8});return true}
  if(this.airDashes>0){this.airDashes--;this.dashDir=dir;this.vx=dir*PHYS.airDash*(this.char.dash||1);this.vy=i.dy<0?-3.5:i.dy>0?5:0;this.noGrav=true;this.setState('airdash');game.fx.dash(this.x,this.y-60,dir);game.sfx('dash',{vol:.7,rate:.8});return true}
  return false}
 tickDash(game){if(this.sf>4&&(this.tryAttack(game)))return;if(this.sf>3&&this.tryJump(game))return;
  if(this.sf>=PHYS.dashFrames){this.vx*=.3;this.setState('idle')}}
 tickAirDash(game){if(this.sf>5&&this.tryAttack(game)){this.noGrav=false;return}
  if(this.sf>=PHYS.airDashFrames){this.noGrav=false;this.vx*=.5;this.setState('air')}}
 // ---------- Moves ----------
 select(b){const i=this.input,g=this.grounded,rel=i.dx*this.facing;this._btn=b;
  if(b==='SUP')return'super';
  if(b==='S'){if(!g)return'airsp';return rel>0?'rising':rel<0?'back':i.dy>0?'rush':'fireball'}
  if(g){const mo=i.motion('dp',this.facing)?'rising':i.motion('qcf',this.facing)?'fireball':i.motion('qcb',this.facing)?'rush':null;
   if(mo){this._mo=1;return mo}
   if(i.dy<=0&&rel>0&&(b==='M'||b==='H'))return'6'+b; // Command-Normal: vorwärts + K / L
   return(i.dy>0?'2':'5')+b}
  return'j'+b}
 canUse(n){const m=this.moves[n];if(!m)return false;if(m.cost&&this.meter<m.cost)return false;if(m.air&&this.grounded)return false;return true}
 rank(n){const m=this.moves[n];if(m.special)return m.super?30:20;return RANK[n.slice(-1)]||0}
 tryAttack(game){const i=this.input;
  for(const b of['SUP','H','M','L','S']){if(!i.pressed(b))continue;const n=this.select(b);
   if(n&&this.canUse(n)){i.consume(b);this.startMove(n,game);return true}}return false}
 startMove(n,game,cancel=false){let m=this.moves[n];
  if(m.v){const vv=m.v[this._btn==='S'?'M':this._btn];if(vv)m={...m,...vv}} // Stärke-Variante (J/K/L) bei Specials
  this.chainLen=cancel?this.chainLen+1:0;this.move=m;this.moveName=n;this.mf=0;this.hitDone=false;this.contact=false;this.hitCd=0;this.noGrav=false;
  if(this._mo){this.input.hist.length=0;this._mo=0}
  if(!m.air&&this.grounded)this.vx=0;
  if(m.cost){this.meter-=m.cost;game.startSuper(this)}
  this.setState('attack')}
 tickAttack(opp,game){const m=this.move;this.mf++;if(this.hitCd>0)this.hitCd--;
  if(m.box&&!m.super){if(this.mf===m.su){const[n,o]=swingSound(m);game.sfx(n,o);if(this.moveName==='rush')game.sfx('dash',{vol:.7,rate:1.1})}                    // Schwung / Rush
   else if(this.mf===m.su+m.ac&&!this.contact&&m.ac<=12&&strike(m).s>=2)game.sfx('whiff_miss',{vol:.45})}                                              // Fehlschlag (nur mittlere/schwere Normals)
  if(m.lunge){if(this.mf<=m.su+m.ac)this.vx=this.facing*m.lunge;else this.vx*=.6}
  else if(!m.air&&this.grounded)this.vx*=.7;
  if(m.rise&&this.mf===m.su){this.vy=m.rise.vy;this.vx=this.facing*m.rise.vx;this.y=GROUND-1}
  if(m.dive&&this.mf===m.su){this.vx=this.facing*m.dive.vx;this.vy=m.dive.vy}
  if(m.tp&&this.mf===m.su)this.teleport(m.tp,opp,game);
  if(m.heal&&this.mf===m.su){this.hp=Math.min(this.maxHp,this.hp+m.heal);game.fx.ps.ring(this.x,this.y-70,'#7dffc8',110)}
  if(m.gain&&this.mf===m.su){this.meter=Math.min(METER.max,this.meter+m.gain);game.fx.ps.ring(this.x,this.y-70,this.char.glow||'#fff',80)}
  if(m.proj)for(const d of[].concat(m.proj))if(this.mf===d.frame)game.spawnProjectile(this,m,d);
  if(this.contact&&this.tryCancel(game))return;
  if(this.mf>=m.su+m.ac+m.rc)this.endMove()}
 // Cancels (nur nach Kontakt): Chain mit steigendem Rang UND Stance-Wechsel (5L→2L→5M→2M→5H ...), Special-/Hyper-Cancel,
 // Jump-Cancel (Launcher), in der Luft Doppelsprung-/Air-Dash-Cancel für lange Mehrfach-Combos. chainLen begrenzt Endlos-Ketten.
 tryCancel(game){const i=this.input,m=this.move,B=PHYS.cancelBuffer;
  if(m.jc&&(i.dy<0||i.pressed('UP',B))){i.consume('UP');this.move=null;this.vy=PHYS.superJumpV*(this.char.jump||1);this.vx=i.dx*PHYS.walk*1.2;this.y=GROUND-1;
   this.airJumps=this.maxAJ;this.airDashes=1;this.setState('air');game.fx.jump(this.x,GROUND);return true}
  if(m.air){
   if(this.airJumps>0&&i.pressed('UP',3)){i.consume('UP');this.move=null;this.vy=PHYS.airJumpV*(this.char.jump||1);this.vx=i.dx*PHYS.walk*1.1*this.char.walk;this.airJumps--;
    this.setState('air');game.fx.ps.ring(this.x,this.y-10,'#9a8bff',40);return true}
   if(this.airDashes>0&&(i.pressed('DASH',4)||i.dashEv)){this.move=null;if(this.tryDash(game))return true;this.move=m}}
  for(const b of['SUP','H','M','L','S']){if(!i.pressed(b,B))continue;const n=this.select(b);if(!n||!this.canUse(n))continue;const nm=this.moves[n];
   let ok;if(nm.special)ok=m.special?(nm.super&&m.spc):m.spc;
   else{const rn=this.rank(n),rc=this.rank(this.moveName);ok=!m.special&&nm.air===m.air&&this.chainLen<6&&(rn>rc||(rn===rc&&n!==this.moveName&&this.chainLen<3))}
   if(ok){i.consume(b);this.startMove(n,game,true);return true}}return false}
 // Teleport: rel 'opp' = relativ zum Gegner (off>0 = auf die abgewandte Seite, flip = dreht sich um), rel 'self' = relativ zu sich (off<0 = zurück)
 teleport(t,opp,game){const gl=this.char.glow||'#fff';game.fx.ps.ring(this.x,this.y-80,gl,90);game.sfx('whoosh_heavy',{rate:.8,vol:.6});
  let nx=(t.rel==='opp'?opp.x:this.x)+this.facing*t.off;nx=Math.max(game.arena.l,Math.min(game.arena.r,nx));this.x=nx;if(t.flip)this.facing=-this.facing;
  game.fx.ps.ring(this.x,this.y-80,gl,90)}
 endMove(){this.move=null;this.setState(this.grounded?'idle':'air')}
 endCombo(){if(this.comboHits>0)this.comboShow={hits:this.comboHits,dmg:this.comboDmg,t:100};this.comboHits=0;this.comboDmg=0;this.juggle=0}
 // ---------- Physik ----------
 physics(game){
  if(!this.noGrav&&(this.y<GROUND||this.vy<0))this.vy+=this.state==='airhit'?PHYS.gravity*.8:PHYS.gravity;
  const px=this.x;this.x+=this.vx;this.y+=this.vy;
  const A=game.arena;
  if(this.x<A.l||this.x>A.r){const fast=Math.abs(this.vx),hurt=['hit','airhit','tumble','ko'].includes(this.state);this.x=this.x<A.l?A.l:A.r;
   if(hurt&&fast>BARRIER.impactV){A.hitWall(game,this,(fast-BARRIER.impactV+1)*BARRIER.impactMul);if(this.x===A.l||this.x===A.r)this.vx=0}} // Aufprall auf die Barriere
  this.ceiling(game,px);
  if(this.y>=GROUND){const fall=this.vy>0;this.y=GROUND;if(fall)this.land(game);this.vy=0}}
 // Decke im Gebäude: Kopf (Höhe der Luft-Hurtbox) darf die Unterkante der Decke nicht überschreiten. Vom Hof aus gilt die Decke als Türsturz:
 // Wer mit dem Kopf darüber liegt, kommt nicht durch die Bresche (wird an der Wandlinie gestoppt), statt in die Decke zu "ploppen".
 ceiling(game,px){const A=game.arena,side=A.inside(this.x);if(!side)return;const hh=132*(this.char.size||1),lim=A.ceil+hh;if(this.y>=lim)return;
  if(!A.inside(px)){this.x=side==='L'?WALL_L:WALL_R;if(this.vx*(side==='L'?-1:1)>0)this.vx=0;return}
  const hit=this.vy<-3;this.y=lim;if(this.vy<0)this.vy=1;
  if(hit){game.particles.burst(this.x,A.ceil+4,{count:7,speed:4,color:'#d8c8a8',life:16,size:2.4,angle:Math.PI/2,spread:1.4,gravity:.25});game.shake=Math.max(game.shake,2);game.sfx('body_fall',{vol:.3,rate:1.4})}}
 land(game){const s=this.state;
  if(s==='airhit'||s==='tumble'){this.launched=false;this.endCombo();this.kdFrames=this.hard?52:36;game.sfx(this.hard?'ground_slam':'body_fall',{vol:this.hard?.9:.85});this.hard=false;this.vx=0;this.setState('knockdown');game.fx.land(this.x,GROUND,true);game.shake=Math.max(game.shake,6);return}
  if(s==='ko'){this.vx=0;game.fx.land(this.x,GROUND,true);game.sfx('body_fall',{vol:.7});return}
  if(s==='attack'){const m=this.move;if(m&&(m.air||m.rise)){this.move=null;this.landLag=m.land||4;this.setState('idle')}}
  else if(s==='airdash'){this.noGrav=false;this.setState('idle')}
  else if(s==='air'){this.setState('idle');this.landLag=3}
  this.airJumps=this.maxAJ;this.airDashes=1;this.vx*=.3;game.fx.land(this.x,GROUND,false);game.sfx('land',{vol:.6})}
 // ---------- Animation (für den Renderer) ----------
 updateAnim(){const s=this.state,m=this.move;this.animU=0;
  switch(s){
   case'idle':this.anim='idle';break;case'walk':this.anim='walk';break;case'crouch':this.anim='crouch';break;case'air':this.anim='air';this.animU=Math.max(0,Math.min(.999,(this.vy+18)/36));break;   // Sprung-Frames nach Flugbahn (steigen -> Scheitel -> fallen)
   case'dash':this.anim='dash';break;case'airdash':this.anim='airdash';break;
   case'attack':this.anim=m?m.anim:'idle';this.animU=m?Math.min(1,this.mf/(m.su+m.ac+Math.max(m.rc,6))):0;break;
   case'hit':this.anim='hit';this.animU=Math.min(1,this.sf/12);break;
   case'block':this.anim=this.blockCrouch?'cblock':'block';break;
   case'airhit':case'tumble':this.anim='airhit';this.animU=Math.min(1,this.sf/34);break;
   case'knockdown':this.anim='kd';this.animU=Math.min(1,this.sf/16);break;
   case'wakeup':this.anim='wakeup';this.animU=Math.min(1,this.sf/18);break;
   case'ko':this.anim=this.grounded?(this.char.defeat?'defeat':'kd'):'airhit';this.animU=Math.min(1,this.sf/(this.grounded?16:34));break;
   case'win':this.anim='win';this.animU=Math.min(.999,this.sf/180);break;default:this.anim='idle'}
  const fast=s==='dash'||s==='airdash'||(s==='attack'&&m&&(m.lunge||m.rise));
  for(const t of this.trail)t.age++;this.trail=this.trail.filter(t=>t.age<14);
  if(fast&&this.sf%3===0)this.trail.push({x:this.x,y:this.y,facing:this.facing,anim:this.anim,animU:this.animU,sf:this.sf,state:s,char:this.char,move:null,age:0})}
}

// ===== core/combat =====



// Trefferauflösung pro Frame: Normals/Specials, Projektile, Projektil-Clash.
function resolveCombat(game){
 const{p1,p2}=game;
 for(const[a,b]of[[p1,p2],[p2,p1]]){
  if(game.phase!=='fight'||b.state==='ko')continue;
  const ah=a.activeHitbox();
  if(ah&&ah.move.unb&&(!b.grounded||['hit','airhit','tumble','knockdown','wakeup'].includes(b.state)))continue; // Griffe: nur gegen Stehende
  if(ah&&ah.rect.overlaps(b.hurtbox())&&!b.invulnerable())hit(game,a,b,ah.move,ah.rect,false)}
 for(const pr of game.projectiles){
  if(pr.dead||pr.cd>0||game.phase!=='fight')continue;const a=pr.owner,b=a===p1?p2:p1;
  if(b.state!=='ko'&&pr.rect().overlaps(b.hurtbox())&&!b.invulnerable()){if(pr.def.pierce)pr.cd=pr.def.pierce;else pr.dead=true;hit(game,a,b,pr.asMove(),pr.rect(),true)}}
 const ps=game.projectiles;
 for(let i=0;i<ps.length;i++)for(let j=i+1;j<ps.length;j++){
  if(ps[i].owner!==ps[j].owner&&!ps[i].dead&&!ps[j].dead&&ps[i].rect().overlaps(ps[j].rect())){
   if(!ps[i].def.pierce)ps[i].dead=true;if(!ps[j].def.pierce)ps[j].dead=true;game.fx.hit((ps[i].x+ps[j].x)/2,ps[i].y,2,'#ffffff',1)}}}
function hit(game,a,b,mv,rect,isProj){
 const hurt=b.hurtbox();
 const sx=(Math.max(rect.x,hurt.x)+Math.min(rect.x+rect.w,hurt.x+hurt.w))/2,sy=(Math.max(rect.y,hurt.y)+Math.min(rect.y+rect.h,hurt.y+hurt.h))/2;
 const col=a.char.glow||'#fff';
 const A=game.arena,pinned=b.grounded&&A.sideAt(b.x)!==null; // Gegner steht an der Barriere (vor dem Treffer geprüft)
 if(!isProj){if(mv.multi)a.hitCd=mv.multi;else a.hitDone=true}
 a.contact=true;
 const def=b.char.def||1,mtr=a.char.meter||1;
 const power=mv.hstop>=11?3:mv.hstop>=8?2:1;
 // ---- Rüstung: steckt den Treffer ein (60 % Schaden), kein Hitstun, Move läuft weiter ----
 if(b.state==='attack'&&b.move&&b.move.armor&&b.mf>=b.move.armor[0]&&b.mf<=b.move.armor[1]&&!mv.unb){
  const ad=Math.max(1,Math.round(mv.dmg*a.dmgMul()*def*.6*COMBO_SCALE[Math.min(b.comboHits,COMBO_SCALE.length-1)]));
  b.hp-=ad;b.armorFlash=8;a.meter=Math.min(METER.max,a.meter+ad*.28*mtr);b.meter=Math.min(METER.max,b.meter+ad*.2);
  game.hitstop=Math.max(game.hitstop,Math.min(mv.hstop,6));game.shake=Math.max(game.shake,3);game.fx.block(sx,sy,'#ffd23f');game.fx.hit(sx,sy,1,'#ffd23f',a.facing);game.sfx('heavy_hit_impact',{vol:.6});
  if(b.hp<=0){b.hp=0;game.knockout(b,a)}return}
 // ---- Block ----
 if(!mv.unb&&b.isBlocking(mv)){
  const chip=Math.round(mv.dmg*a.dmgMul()*def*.1);b.hp=Math.max(1,b.hp-chip);
  b.blockCrouch=b.grounded&&b.input.dy>0;b.move=null;b.state='block';b.sf=0;b.stun=mv.bs;b.vx=a.facing*mv.pbb;
  if(pinned)a.vx=-a.facing*mv.pbb;
  if(pinned)A.hitWall(game,b,mv.dmg*a.dmgMul()*BARRIER.hitMul*BARRIER.blockMul,{launch:false});
  game.hitstop=Math.max(game.hitstop,Math.min(mv.hstop,6));
  a.meter=Math.min(METER.max,a.meter+mv.dmg*.05*mtr);b.meter=Math.min(METER.max,b.meter+mv.dmg*.04);
  game.fx.block(sx,sy,col);game.sfx('block_guard');game.camera.kick(.004);game.kickX+=a.facing*2;return}
 // ---- Treffer: Schadensskalierung pro Combo-Treffer ----
 const scale=Math.max(COMBO_SCALE[Math.min(b.comboHits,COMBO_SCALE.length-1)],mv.minScale||0);
 const dmg=Math.max(1,Math.round(mv.dmg*a.dmgMul()*scale*def));
 b.hp-=dmg;b.comboHits++;b.comboDmg+=dmg;b.comboShow={hits:b.comboHits,dmg:b.comboDmg,t:100};b.comboFlash=10;
 a.meter=Math.min(METER.max,a.meter+dmg*.28*mtr);b.meter=Math.min(METER.max,b.meter+dmg*.14);
 const air=!b.grounded;
 b.move=null;b.noGrav=false;
 const lastMulti=!mv.multi||a.mf>=mv.su+mv.ac-mv.multi;
 const launch=mv.launch&&lastMulti?mv.launch:null;
 if(launch||air||mv.hard){
  b.juggle=air?b.juggle+1:1;
  let vy=launch?launch.vy*(air?.8:1):-9,vx=launch?launch.vx:3;
  if(b.juggle>PHYS.juggleMax)vy=Math.max(vy,2); // Juggle-Limit: danach fällt der Gegner
  if(launch||mv.hard)b.launched=true;           // Launcher/harter Treffer: keine Luft-Erholung mehr -> Knockdown bei der Landung
  b.state='airhit';b.stun=b.launched?9999:Math.max(mv.hs,34); // großzügiger Luft-Hitstun für Mehrfach-Combos
  if(mv.hard){b.state='tumble';vy=11;vx=3.2;b.hard=true}
  b.sf=0;b.vx=a.facing*vx;b.vy=vy;b.y=Math.min(b.y,GROUND-1)}
 else{b.state='hit';b.sf=0;b.stun=mv.hs;b.vx=a.facing*mv.pb}
 let broke=false;
 if(pinned&&b.hp>0){const heavy=launch||mv.hard?BARRIER.heavyMul:1;broke=A.hitWall(game,b,mv.dmg*a.dmgMul()*BARRIER.hitMul*heavy)}     // Wand nimmt Schaden; bricht sie, fliegt b hindurch
 if(!air&&pinned&&!broke&&!mv.multi)a.vx=-a.facing*mv.pb;
 game.hitstop=Math.max(game.hitstop,mv.hstop);game.shake=Math.max(game.shake,b.comboHits>=2?EFFECT.comboShake:mv.shake||power*1.5);
 game.fx.hit(sx,sy,power,col,a.facing);game.hitFeel(sx,sy,a.facing,power,dmg,col,{launch:!!launch,hard:!!mv.hard,hits:b.comboHits});
 game.sfxList(hitSounds(mv,{launch:!!launch,proj:isProj}));
 if(b.comboHits>=2){game.fx.combo(sx,sy,b.comboHits,col,a.facing);}
 if(b.hp<=0){b.hp=0;game.knockout(b,a)}}

// ===== core/ai =====

// Schwierigkeitsstufen. Alle Werte hier justierbar:
//  wait   = Pause zwischen Entscheidungen in Frames [min,max]     idle   = Chance, eine Entscheidung "zu verschlafen"
//  react  = Reaktionszeit in Frames, bevor geblockt werden kann    block  = Blockchance pro Angriff
//  combo  = Chance, nach einem Treffer weiterzumachen              maxChain = max. Folgeschritte (Chain/Launcher/Luft-Combo)
//  special/sup/dash = Anteil Specials / Hypers / Dashes            antiair = Chance auf Anti-Air   back = Chance auf Rückzug
//  aerial = Luft-Angriffschance pro Frame in der Luft              dmg = Schadensfaktor der KI
//  corner = Wie konsequent die KI einen Gegner an der Wand/in der Ecke bearbeitet (weniger Abwarten/Rückzug, Druck, Launcher) und selbst aus der Ecke ausbricht
const AI_LEVELS=[
 {name:'LEICHT',wait:[75,140],idle:.4,react:24,block:.05,combo:.08,maxChain:1,special:.06,sup:0,dash:.03,jump:.004,antiair:.1,back:.3,aerial:.01,dmg:.7,corner:.12},
 {name:'NORMAL',wait:[42,85],idle:.2,react:13,block:.28,combo:.35,maxChain:2,special:.16,sup:.08,dash:.1,jump:.01,antiair:.35,back:.15,aerial:.03,dmg:.9,corner:.5},
 {name:'HART',wait:[24,50],idle:.06,react:7,block:.48,combo:.55,maxChain:4,special:.24,sup:.25,dash:.2,jump:.02,antiair:.6,back:.06,aerial:.06,dmg:1,corner:.85}];
// KI nutzt dieselbe Eingabe-Schnittstelle wie der Spieler (vereinfachte Special-Eingaben: Taste + Richtung).
class AIController extends InputBuffer{
 constructor(level=0){super();this.keep={dx:0,dy:0,n:0};this.cd=0;this.setLevel(level)}
 setLevel(l){this.level=Math.max(0,Math.min(AI_LEVELS.length-1,l|0));this.P=AI_LEVELS[this.level];
  this.wait=this.P.wait[1];this.seen=null;this.seenP=null;this.seenAge=0;this.blockRoll=false;this.blockN=0;this.chain=0;this.keep={dx:0,dy:0,n:0}}
 tick(me,opp,game){
  const P=this.P,R=Math.random,pr=[];let dx=0,dy=0;
  if(game.phase!=='fight'){this.feed(0,0,[]);return}
  const fwd=opp.x>=me.x?1:-1,dist=Math.abs(opp.x-me.x),frozen=game.hitstop>0||game.superFlash>0;
  if(this.keep.n>0){this.keep.n--;dx=this.keep.dx;dy=this.keep.dy}
  const go=(btn,x=0,y=0,n=3)=>{if(btn)pr.push(btn);dx=x;dy=y;this.keep={dx:x,dy:y,n}};
  const walk=(x,y,n)=>{this.keep={dx:x,dy:y,n};dx=x;dy=y};
  if(this.cd>0)this.cd--;
  // --- Verteidigung: erst nach der Reaktionszeit blocken; sehr schnelle Angriffe kommen durch ---
  const om=opp.state==='attack'?opp.move:null,pj=game.projectiles.find(p=>p.owner===opp&&Math.abs(p.x-me.x)<230);
  if(om&&om!==this.seen){this.seen=om;this.seenAge=0;this.blockRoll=R()<P.block;this.blockN=om.su+om.ac+6}
  else if(pj&&pj!==this.seenP){this.seenP=pj;this.seen=null;this.seenAge=0;this.blockRoll=R()<P.block;this.blockN=26}
  else if(!om&&!pj)this.seen=null;
  if(om||pj)this.seenAge++;
  if(this.blockN>0)this.blockN--;
  if(this.blockRoll&&this.blockN>0&&this.seenAge>=P.react&&me.grounded&&['idle','walk','crouch','block','dash'].includes(me.state)){
   this.feed(-fwd,om&&om.lv==='low'?1:0,[],frozen);return}
  // --- Combo-Fortsetzung (gestuft: maxChain begrenzt die Länge) ---
  if(me.state==='attack'&&me.contact&&this.cd<=0){
   if(this.chain<P.maxChain){
    if(R()<P.combo){const mn=me.moveName,r=R();this.cd=3;this.chain++;
     if(mn==='5L'||mn==='2L')go(r<.5?'M':'H',0,r<.4?1:0);
     else if(mn==='5M'||mn==='2M')r<.55?go('H',0,1):go('S');
     else if(mn==='5H')go('S');
     else if(mn==='2H'){walk(fwd,-1,5)}
     else if(mn==='jL')go('M');else if(mn==='jM')go('H');
     else if((mn==='rising'||mn==='fireball'||mn==='rush')&&me.meter>=100&&R()<P.sup*3)go('SUP')}
    else this.chain=99}}
  else if(me.state==='air'&&!me.move&&this.cd<=0&&dist<140){
   if(!opp.grounded||opp.state==='airhit'||opp.state==='tumble'){if(R()<P.combo){this.cd=3;go('L')}}
   else if(R()<P.aerial){this.cd=10;go(R()<.25?'S':R()<.5?'M':'H')}}
  // --- Neutral: seltener und ruhiger entscheiden ---
  else if(this.wait>0)this.wait--;
  else if(!['attack','hit','block','knockdown','wakeup','airhit','tumble','ko'].includes(me.state)){
   const A=game.arena,oppGap=fwd>0?A.r-opp.x:opp.x-A.l,pin=oppGap<150&&opp.grounded;                    // Gegner steht vor der Wand
   this.wait=Math.round((P.wait[0]+(R()*(P.wait[1]-P.wait[0])|0))*(pin?1-.45*P.corner:1));this.chain=0;const r=R();
   if(R()<P.idle*(pin?1-.85*P.corner:1))walk(0,0,18);                                          // abwarten
   else if(!opp.grounded&&dist<170&&me.grounded){if(R()<P.antiair)go('S',fwd,0,4)}
   else if(opp.state==='knockdown'||opp.state==='wakeup'){if(dist>100)walk(fwd,0,16);else go(r<.5?'M':'L')}
   else if(this.corner(me,opp,dist,fwd,go,walk,game)){}                                 // Ecke: Druck machen bzw. ausbrechen
   else if(this.tool(me,dist,fwd,go)){}                                  // figurentypische Moves (char.ai)
   else if(dist>300){if(r<P.special)go('S');else if(r<P.special+P.dash)go('DASH',fwd);else if(R()<P.jump*8)walk(fwd,-1,5);else walk(fwd,0,25)}
   else if(dist>150){
    if(r<P.special)go('S');else if(r<P.special+P.sup&&me.meter>=100)go('SUP');else if(r<P.special+P.sup+.12)go('S',0,1);
    else if(r<P.special+P.sup+.12+P.dash)go('DASH',fwd);else walk(fwd,0,14)}
   else if(dist>95){if(r<.35)go('M');else if(r<.5)go('M',0,1);else if(r<.65)go('H');else walk(fwd,0,8)}
   else{if(R()<P.back&&(fwd>0?me.x-game.arena.l:game.arena.r-me.x)>120)walk(-fwd,0,20);else if(r<.4)go('L');else if(r<.6)go('L',0,1);else if(r<.8)go('M');else go('H',0,1)}}
  // KI in der Luft: Luft-Special gelegentlich
  this.feed(dx,dy,pr,frozen)}
 // Wand-Taktik: Steht der Gegner vor der Wand, setzt die KI nach (Dash, Projektil, Normals, Launcher = 1,5× Wandschaden). Steht sie selbst
 // mit dem Rücken zur Wand, bricht sie aus (Sprung über den Gegner) statt weiter zurückzuweichen. Chance skaliert mit P.corner (je Stufe).
 corner(me,opp,dist,fwd,go,walk,game){const P=this.P,A=game.arena,R=Math.random;if(!P.corner)return false;
  const oppGap=fwd>0?A.r-opp.x:opp.x-A.l,meGap=fwd>0?me.x-A.l:A.r-me.x;
  if(meGap<100&&dist<190&&R()<P.corner*.7){if(R()<.55)walk(fwd,-1,6);else go('M');return true}
  if(oppGap>=150||!opp.grounded||R()>=P.corner)return false;
  const r=R();
  if(dist>200){if(r<.45)go('DASH',fwd);else if(r<.65)go('S');else walk(fwd,0,20)}
  else if(dist>110){if(r<.3)go('M');else if(r<.5)go('S');else walk(fwd,0,10)}
  else{if(r<.25)go('L');else if(r<.4)go('L',0,1);else if(r<.65)go('M');else if(r<.85)go('H',0,1);else go('H')}
  return true}
 // Figurenspezifische Werkzeuge (Griff, Teleport, Falle ...): Liste char.ai = [{min,max,b,dx,dy,p}], Chance skaliert mit der Stufe
 tool(me,dist,fwd,go){const L=me.char.ai;if(!L)return false;const k=[.45,.8,1][this.level];
  for(const t of L){if(dist<t.min||dist>=t.max)continue;if(Math.random()<t.p*k){go(t.b,(t.dx||0)*fwd,t.dy||0,4);return true}}return false}
}

// ===== core/arcade =====


// Arcade-Modus: Charakterwahl -> nacheinander gegen alle anderen spielbaren Figuren (je 2 Runden-Siege = Stage geschafft)
// -> Endgegner Minotaurus. Zustände: select | fight | clear | gameover | victory. Rein logisch (kein DOM) -> testbar.
class Arcade{
 constructor(game,p1,p2,ai){this.game=game;this.p1=p1;this.p2=p2;this.ai=ai;this.state='select';this.cursor=0;this.difficulty=0;
  this.opponents=[];this.stage=0;this.t=0;this.player=null;game.arcade=this;
  this.mode='arcade';this.vs={c1:0,c2:1,locked:[false,false],step:0,stage:0};this.vsStage=0;this.stageCount=4}
 get total(){return this.opponents.length}
 get isBoss(){return this.opponents[this.stage]===BOSS}
 opponentName(i=this.stage){const id=this.opponents[i];return id?CHARACTERS[id].name:''}
 static ladderFor(playerId){return[...LADDER.filter(x=>x!==playerId),BOSS]}
 start(playerId){this.player=playerId;this.opponents=Arcade.ladderFor(playerId);this.stage=0;this.p1.setChar(CHARACTERS[playerId]);this.beginStage()}
 beginStage(){const g=this.game;this.p2.setChar(CHARACTERS[this.opponents[this.stage]]);this.applyDifficulty();
  g.stageIndex=this.isBoss?this.stageCount-1:this.stage%(this.stageCount-1);   // Boss immer in der letzten Arena (Labyrinth); bei mehr Gegnern als Arenen wiederholen sich die ersten
  g.rematch();this.state='fight';this.t=0}
 // Endgegner ist eine Stufe härter als die gewählte Schwierigkeit (max. HART)
 applyDifficulty(){this.ai.setLevel(Math.min(2,this.difficulty+(this.isBoss?1:0)))}
 setDifficulty(d){this.difficulty=Math.max(0,Math.min(2,d|0));if(this.state!=='select')this.applyDifficulty()}
 retry(){this.game.rematch();this.state='fight';this.t=0}
 toSelect(){this.state='select';this.game.stageIndex=0;this.t=0;this.vsReset()}
 // ---- 2-Spieler-Modus (PvP): beide wählen einen Kämpfer, danach die Stage ----
 static slotIds(){return[...ROSTER,...(CHARACTERS.custom?['custom']:[])]}
 setMode(m){if(this.state!=='select')return;this.mode=m==='versus'?'versus':'arcade';this.vsReset()}
 toggleMode(){this.setMode(this.mode==='versus'?'arcade':'versus')}
 vsReset(){const n=Arcade.slotIds().length;this.vs={c1:Math.min(this.vs.c1,n-1),c2:Math.min(this.vs.c2,n-1),locked:[false,false],step:0,stage:this.vs.stage||0}}
 vsMove(pl,dir){const v=this.vs,n=Arcade.slotIds().length;if(v.step!==0||v.locked[pl-1])return;const k=pl===1?'c1':'c2';v[k]=(v[k]+dir+n)%n}
 vsSet(pl,i){const v=this.vs;if(v.step!==0||v.locked[pl-1])return;v[pl===1?'c1':'c2']=Math.max(0,Math.min(Arcade.slotIds().length-1,i|0))}
 vsConfirm(pl){const v=this.vs;if(v.step!==0||v.locked[pl-1])return;v.locked[pl-1]=true;if(v.locked[0]&&v.locked[1])v.step=1}
 vsBack(){const v=this.vs;if(v.step===1){v.step=0;v.locked=[false,false]}else if(v.locked[1])v.locked[1]=false;else if(v.locked[0])v.locked[0]=false}
 vsStageMove(dir){const v=this.vs;if(v.step!==1)return;const n=this.stageCount+1;v.stage=(v.stage+dir+n)%n}   // letzte Karte = Zufall
 vsStart(){const v=this.vs,ids=Arcade.slotIds();if(v.step!==1)return false;this.startVersus(ids[v.c1],ids[v.c2],v.stage>=this.stageCount?-1:v.stage);return true}
 startVersus(id1,id2,stage=0){this.mode='versus';this.player=id1;this.opponents=[];this.stage=0;this.vsStage=stage;this.p1.setChar(CHARACTERS[id1]);this.p2.setChar(CHARACTERS[id2]);this.beginVersus()}
 beginVersus(){const g=this.game,st=this.vsStage;g.stageIndex=st<0?Math.floor(Math.random()*this.stageCount):st;g.rematch();this.state='fight';this.t=0}
 rematchVs(){this.beginVersus()}
 next(){this.stage++;this.beginStage()}
 // Enter-Taste: je nach Zustand weiter / nochmal / zurück zur Auswahl
 confirm(){if(this.state==='vsover')this.rematchVs();else if(this.state==='clear')this.next();else if(this.state==='gameover')this.retry();else if(this.state==='victory')this.toSelect()}
 // nach jedem game.step(): Match-Ende auswerten
 update(){const g=this.game;
  if(this.state==='fight'&&g.phase==='match'&&g.pf>=70){
   if(this.mode==='versus')this.state='vsover';else if(this.p1.wins>=ROUND.wins)this.state=this.stage>=this.total-1?'victory':'clear';else this.state='gameover';this.t=0}
  else if(this.state==='clear'){if(++this.t>=240)this.next()}   // automatisch weiter (Enter überspringt)
  else this.t++}
}

// ===== core/game =====








const SUPER_FRAMES=42;   // Länge des Super-Freeze (muss zu hud.flash passen)
// Spielzustand + fester 60-Hz-Schritt. Keine DOM-Abhängigkeit -> headless testbar.
// Phasen: intro -> fight -> ko -> result -> (intro | match)
class Game{
 constructor(p1,p2){this.p1=p1;this.p2=p2;this.fighters=[p1,p2];this.particles=new ParticleSystem();this.fx=new Effects(this.particles);
  this.camera=new Camera();this.arena=new Arena();this.stageIndex=0;this.arcade=null;this.debug=false;this.round=1;this.frame=0;this.flash=0;this.flashColor='#fff';
  this.pops=[];this.kickX=0;this.kickY=0;this.aberr=0;this.impact=null;this.slow=0;this.timeScale=1;this.celeb=null;this.particles.onBoom=()=>this.sfx('heavy_hit_impact',{vol:.3,rate:.8+Math.random()*.25});this.startRound()}
 // Sound: game.audio (render/audio.js) ist im Test/headless null -> kein Ton. sfx() für einzelne Sounds, sfxList() für Listen aus core/sfx.js
 sfx(n,o){if(this.audio)this.audio.play(n,o)}
 sfxList(l){if(this.audio)for(const[n,o]of l)this.audio.play(n,o)}
 startRound(){this.cineW=0;this.cineT=0;this.arena.reset();this.pops=[];this.kickX=this.kickY=0;this.aberr=0;this.impact=null;this.celeb=null;this.slow=0;this.timeScale=1;this.sfx('ui_round_start',{vol:.8});this.projectiles=[];this.phase='intro';this.pf=0;this.timeFrames=ROUND.time*60;this.hitstop=0;this.superFlash=0;this.superOwner=null;this.shake=0;this.flash=0;this.winner=null;this.timedOut=false;
  for(const f of this.fighters){f.reset();f.input.clear()}this.camera.snap(this.fighters)}
 rematch(){this.round=1;for(const f of this.fighters){f.wins=0;f.meter=0}this.startRound()}
 spawnProjectile(f,mv,d=mv.proj){this.sfx('whoosh_heavy',{vol:.6,rate:.85});if(d.uniq)for(const p of this.projectiles)if(p.owner===f&&p.def.uniq===d.uniq)p.dead=true;this.projectiles.push(new Projectile(f,mv,d))}
 // Schadenszahl / Text-Pop (Welt-Koordinaten); kind: 'dmg' | 'text'
 pop(x,y,s,col,size=1,o={}){if(this.pops.length>14)this.pops.shift();this.pops.push({x,y,s:String(s),col:col||'#fff',size,age:0,life:o.life||46,dx:o.dx!==undefined?o.dx:(Math.random()-.5)*34,rot:(Math.random()-.5)*.18,text:!!o.text,tech:!!o.tech})}
 // Treffer-Feedback: Zoom-Punch, Rückstoß der Kamera, Farbsäume, Impact-Frame, Schadenszahl
 hitFeel(x,y,dir,power,dmg,col,o={}){const E=EFFECT,big=power>=3||o.launch||o.hard;
  this.camera.kick(big?E.punchBig:power>=2?E.punchMid:E.punchSmall);this.kickX+=dir*(big?E.kickBig:E.kickSmall);this.kickY+=big?-3:-1;
  this.aberr=Math.max(this.aberr,big?.9:power>=2?.45:.18);
  if(big){this.impact={t:7,t0:7,x,y,col,p:1,seed:Math.random()*99};this.flash=Math.max(this.flash,3);this.flashColor='#ffffff'}
}
 startSuper(f){this.aberr=1;this.camera.kick(.05);this.superName=(f.move&&f.move.label)||'';this.sfx('heavy_hit_impact');this.superFlash=SUPER_FRAMES;this.superOwner=f;this.shake=EFFECT.superShake;this.flash=EFFECT.screenFlash;this.flashColor=f.char.glow||'#fff';this.fx.ps.ring(f.x,f.y-80,'#ffffff',160)}
 knockout(victim,attacker){this.sfx('ko_hit');this.slow=this.slowMax=EFFECT.koSlow;this.aberr=1;this.camera.kick(.07);this.kickX+=attacker.facing*14;this.impact={t:10,t0:10,x:victim.x,y:victim.y-80,col:victim.char.glow||'#fff',p:1.2,seed:Math.random()*99};victim.state='ko';victim.sf=0;victim.vy=-9;victim.vx=attacker.facing*6;victim.noGrav=false;victim.move=null;
  this.phase='ko';this.pf=0;this.winner=attacker;this.hitstop=26;this.shake=EFFECT.koShake;this.flash=EFFECT.screenFlash;this.flashColor=victim.char.glow||'#fff';this.fx.ko(victim.x,victim.y-80,victim.char.glow||'#fff')}
 // Hyper-Kamerafahrt: weich auf den Angreifer zoomen und im Zoom bleiben, solange sein Hyper-Move aktiv ist (inkl. Freeze); `lead` Frames vor Ende der aktiven Phase sanft zurück
 cineCamera(){const f=this.superOwner,K=CAMERA.cine;
  const m=f&&f.move,on=!!f&&(this.superFlash>0||(m&&m.super&&f.mf<m.su+m.ac-K.lead))&&this.cineT<K.maxF;   // Rauszoomen beginnt schon vor dem letzten Treffer
  if(on){this.cineT++;this.cineW=Math.min(1,this.cineW+1/K.inF)}else{this.cineW=Math.max(0,this.cineW-1/K.outF);if(this.cineW<=0)this.cineT=0}
  if(!f||this.cineW<=0){this.camera.focus(null);return}
  const o=f===this.p1?this.p2:this.p1,sz=(f.char&&f.char.size)||1,w=this.cineW*this.cineW*(3-2*this.cineW);
  const fit=W/(Math.abs(o.x-f.x)+K.margin*2);   // nie so dicht, dass der Gegner aus dem Bild fällt
  this.camera.focus(f.x+(o.x-f.x)*K.bias,f.y-K.lift*sz,Math.max(1,Math.min(K.zoom/Math.sqrt(sz),fit)),w)}
 step(){
  this.frame++;
  for(const f of this.fighters)f.input.tick(f,f===this.p1?this.p2:this.p1,this);
  this.particles.update();this.arena.update();
  if(this.celeb){this.celeb.t++;this.fx.celebrate(this.celeb.f,this.celeb.t,this.camera)}
  this.kickX*=.78;this.kickY*=.78;this.aberr*=.86;if(this.aberr<.01)this.aberr=0;if(this.impact&&--this.impact.t<=0)this.impact=null;
  for(const p of this.pops)p.age++;this.pops=this.pops.filter(p=>p.age<p.life);
  if(this.slow>0){this.slow--;const u=1-this.slow/this.slowMax;this.timeScale=EFFECT.koSlowMin+(1-EFFECT.koSlowMin)*u*u}else this.timeScale=1;  // Zeitlupe beim K.O. (Hauptschleife teilt die Schrittlänge dadurch)
  this.cineCamera();
  this.camera.update(this.fighters); // läuft auch im Hitstop/Super-Flash weiter
  if(this.shake>0)this.shake=Math.max(0,this.shake-.4);
  if(this.flash>0)this.flash--;
  if(this.superFlash>0){this.superFlash--;return}
  if(this.hitstop>0){this.hitstop--;return}
  switch(this.phase){
   case'intro':this.pf++;for(const f of this.fighters){f.sf++;f.updateAnim()}
    if(this.pf>=ROUND.intro){this.phase='fight';this.pf=0;for(const f of this.fighters)f.input.clear()}break;
   case'fight':this.simulate(true);if(--this.timeFrames<=0&&this.phase==='fight')this.timeUp();break;
   case'ko':this.pf++;if(this.pf<70&&this.frame%2)break;this.simulate(false);if(this.pf>=ROUND.ko)this.endRound();break;
   case'result':this.pf++;this.simulate(false);if(this.pf>=ROUND.result){
     const w=this.fighters.find(f=>f.wins>=ROUND.wins);if(w){this.phase='match';this.pf=0}else{this.round++;this.startRound()}}break;
   case'match':this.pf++;this.simulate(false);break}}
 simulate(combat){const[a,b]=this.fighters;a.update(b,this);b.update(a,this);
  for(const p of this.projectiles)p.update();
  if(combat)resolveCombat(this);
  this.projectiles=this.projectiles.filter(p=>!p.dead);
  this.separate(a,b);
  for(const f of this.fighters)f.updateAnim()}
 // Körper nicht übereinanderlaufen lassen (Wand-sicher)
 separate(a,b){if(Math.abs(a.y-b.y)>90)return;if(['knockdown','ko'].includes(a.state)||['knockdown','ko'].includes(b.state))return;
  const min=48,d=b.x-a.x,ad=Math.abs(d);if(ad>=min)return;const s=d>=0?1:-1,push=(min-ad)/2;
  a.x-=s*push;b.x+=s*push;
  const WL=this.arena.l,WR=this.arena.r;for(const f of[a,b]){if(f.x<WL){const o=WL-f.x;f.x=WL;(f===a?b:a).x+=o}if(f.x>WR){const o=f.x-WR;f.x=WR;(f===a?b:a).x-=o}}}
 timeUp(){const[a,b]=this.fighters;this.winner=a.hp>b.hp?a:b.hp>a.hp?b:null;this.timedOut=true;this.endRound()}
 endRound(){if(this.winner){this.winner.wins++;this.shake=Math.max(this.shake,EFFECT.winShake);this.fx.win(this.winner.x,this.winner.y-80,this.winner.char.glow||'#fff');this.celeb={f:this.winner,t:0};this.camera.kick(.06);this.flash=EFFECT.screenFlash;this.flashColor='#ffffff';if(this.winner.grounded&&this.winner.state!=='ko'){this.winner.setState('win')}}
  this.phase='result';this.pf=0}
}

