// Eigene Figur (Upload im Startmenü): Sprite-Definition zur Laufzeit eintragen; Atlas liefert window.__SPRITES__[id]={meta,img}
function registerSpriteChar(id,def){SPRITE_CHARS[id]=def}
function sheet(id){const S=typeof window!=='undefined'&&window.__SPRITES__&&window.__SPRITES__[id];if(!S||typeof Image==='undefined')return null;
 if(!S.img){S.img=new Image();S.img.src=S.atlas||('assets/'+id+'/atlas.webp');
  const C=SPRITE_CHARS[id];if(C&&S.meta&&S.meta.anims)Object.assign(C.anims,S.meta.anims)}   // Animationen aus dem Atlas (z. B. Tiger-Sheets via tools/import-tiger-sheets.py) überschreiben die Behelfe
 return S}
const ready=S=>S.img.complete&&(S.img.naturalWidth===undefined||S.img.naturalWidth>0);
const fightK=(C,f)=>C.fightScale&&!f.menu&&!(C.fullAnims&&C.fullAnims.includes(f.anim))?C.fightScale:1;   // Menü-Figuren (f.menu) werden nie verkleinert
function drawSpriteFighter(g,f,clock,alpha=1,floorY=470){
 const C=SPRITE_CHARS[f.char.sprites],S=sheet(f.char.sprites);
 g.save();g.globalAlpha=alpha;
 if(alpha===1){g.fillStyle='#0008';g.beginPath();g.ellipse(f.x,floorY+4,Math.max(18,56-(floorY-f.y)*.15)*(C?fightK(C,f):1),10,0,0,7);g.fill()}
 if(!C||!S||!ready(S)){g.restore();return}
 const fs=fightK(C,f);   // Kampfpose = skaliert
 const M=S.meta,k=C.height/M.standH*fs,a=C.anims[f.anim]||C.anims.idle,n=a.frames.length;
 const idx=a.loop?Math.floor(f.sf/60*a.fps)%n:Math.min(n-1,Math.floor(Math.min(f.animU,.999)*n));
 const fr=M.frames[a.frames[idx]]||M.frames.idle_0||M.frames[C.anims.idle.frames[0]];if(!fr){g.restore();return}
 g.translate(f.x,f.y);g.scale(f.facing,1);
 if(a.flip)g.scale(-1,1);
 if(f.state==='tumble'){g.translate(0,-80);g.rotate(-f.sf*.3);g.translate(0,80)}                  // Rotation beim harten Knockdown
 if(a.shiftX)g.translate(a.shiftX,0);
 if(a.lying){g.translate(0,-28);g.rotate(-1.45*(a.rise?1-Math.min(1,f.animU*1.15):1));g.translate(0,80)}   // liegend (Knockdown/KO), mit 'rise' stufenlos aufrichten
 if(a.bob)g.translate(0,-Math.abs(Math.sin(f.sf*.28))*a.bob);
 if(a.lean)g.rotate(a.lean);
 if(a.squash)g.scale(1,a.squash);
 g.imageSmoothingEnabled=true;g.imageSmoothingQuality='high';
 g.drawImage(S.img,fr.x,fr.y,fr.w,fr.h,fr.ox*k,fr.oy*k,fr.w*k,fr.h*k);
 if(a.flip)g.scale(-1,1);                                                                          // Effekte wieder in Blickrichtung
 attackFx(g,f,fs===1?C.fist:[C.fist[0]*fs,C.fist[1]*fs],f.char.glow);
 g.restore()}
// Projektil als Sprite (z. B. Zauberin: rotierender Ring). Gibt false zurück, wenn die Figur kein Projektil-Sprite hat.
function drawSpriteProjectile(g,p,owner){
 const C=SPRITE_CHARS[owner.char.sprites],S=C&&C.proj&&!(p.def.look&&p.def.look!=='ring')&&sheet(owner.char.sprites);if(!S||!ready(S))return false;
 const M=S.meta,fr=M.frames[C.proj[Math.floor(p.age/5)%C.proj.length]];if(!fr)return false;const sc=(C.projScale||.8)*Math.min(1.5,Math.max(.55,p.w/96));
 g.save();g.translate(p.x,p.y);g.rotate(p.age*.12*Math.sign(p.vx));g.globalCompositeOperation='lighter';g.globalAlpha=.95;
 const gr=g.createRadialGradient(0,0,4,0,0,60);gr.addColorStop(0,'#ff3a3a66');gr.addColorStop(1,'#0000');g.fillStyle=gr;g.beginPath();g.arc(0,0,60,0,7);g.fill();
 g.globalCompositeOperation='source-over';g.globalAlpha=1;g.drawImage(S.img,fr.x,fr.y,fr.w,fr.h,-fr.w*sc/2,-fr.h*sc/2,fr.w*sc,fr.h*sc);g.restore();return true}

// Portrait für das HUD: Kopf/Oberkörper-Ausschnitt des ersten Idle-Frames (Sprite-Figuren); false = kein Sprite (HUD zeichnet den Anfangsbuchstaben)
function drawPortrait(g,char,cx,cy,size,flip){
 const C=char.sprites&&SPRITE_CHARS[char.sprites],S=C&&sheet(char.sprites);if(!S||!ready(S))return false;
 const fr=S.meta.frames[C.anims.idle.frames[0]];if(!fr)return false;
 const cw=fr.w*.86,ch=Math.min(fr.h,cw),sx=fr.x+(fr.w-cw)/2;
 g.save();g.translate(cx,cy);if(flip)g.scale(-1,1);g.imageSmoothingEnabled=true;g.imageSmoothingQuality='high';
 g.drawImage(S.img,sx,fr.y,cw,ch,-size/2,-size/2,size,size*ch/cw);g.restore();return true}

// Kompletter erster Idle-Frame, in die Box (x,y,w,h) eingepasst (nichts abgeschnitten), unten mittig ausgerichtet
function drawFullFrame(g,char,x,y,w,h){
 const C=char.sprites&&SPRITE_CHARS[char.sprites],S=C&&sheet(char.sprites);if(!S||!ready(S))return false;
 const pa=C.profileAnim&&C.anims[C.profileAnim],fr=S.meta.frames[pa?pa.frames[pa.frames.length-1]:C.anims.idle.frames[0]];if(!fr)return false;   // Profil: Siegerpose, falls profileAnim gesetzt
 const k=Math.min(w/fr.w,h/fr.h),dw=fr.w*k,dh=fr.h*k;
 g.save();g.imageSmoothingEnabled=true;g.imageSmoothingQuality='high';g.drawImage(S.img,fr.x,fr.y,fr.w,fr.h,x+(w-dw)/2,y+h-dh,dw,dh);g.restore();return true}

// ===== render/audio =====
// WebAudio-Soundbank. Samples liegen als Data-URI in window.__SFX__ (vom Build aus /sfx eingebettet, läuft also per Doppelklick).
// Browser starten Audio erst nach einer Nutzer-Geste -> unlock() beim ersten Tastendruck/Klick. Leichte Tonhöhen-Variation gegen Wiederholung,
// Mindestabstand je Sound (Mehrfachtreffer/Hyper-Beam) und Stimmen-Limit. Kompressor am Ausgang, damit geschichtete Treffer nicht übersteuern.
// Hintergrundmusik: Tracks (music/<name>.ogg, vom Build als Data-URI in window.__MUSIC__) laufen als Loop auf eigenem Bus (nicht durch Kompressor/Tiefpass der Effekte).
// 'menu' = Charakter-/Stage-Auswahl, 'fight' = Kämpfe. Pegel je Track relativ zur Gesamtlautstärke, damit Treffer-Sounds obenauf bleiben. Wechsel per Crossfade.
const MUSIC_VOL={menu:.8,fight:.7},FADE_IN=.9,FADE_OUT=.7;
const GAP={block_guard:45,body_fall:60,whoosh_light:40,whoosh_heavy:40,land:60,punch_light:35,punch_medium:35,punch_heavy:35,kick_light:35,kick_heavy:35,heavy_hit_impact:50,hit_critical:120,ko_hit:400,ui_round_start:600};
class Sound{
 constructor(){this.vol=.7;this.muted=false;this.ctx=null;this.master=null;this.buf={};this.last={};this.voices=0;this.src=(typeof window!=='undefined'&&window.__SFX__)||{};
  this.msrc=(typeof window!=='undefined'&&window.__MUSIC__)||{};this.mbuf={};this.mvol=1;this.mmuted=false;this.want=null;this.cur=null;this.node=null;this.mbus=null}
 get available(){return Object.keys(this.src).length>0||Object.keys(this.msrc).length>0}
 // Muss aus einer Nutzer-Geste heraus aufgerufen werden (keydown/pointerdown)
 unlock(){const AC=window.AudioContext||window.webkitAudioContext;if(!AC||!this.available)return;
  if(!this.ctx){try{this.ctx=new AC()}catch(e){return}
   const c=this.ctx,comp=c.createDynamicsCompressor();this.master=c.createGain();if(c.createBiquadFilter){const lp=c.createBiquadFilter();lp.type='lowpass';lp.frequency.value=6500;lp.Q.value=.5;this.master.connect(lp);lp.connect(comp)}else this.master.connect(comp);comp.connect(c.destination);this.mbus=c.createGain();const lim=c.createDynamicsCompressor();if(lim.threshold){lim.threshold.value=-4;lim.knee.value=0;lim.ratio.value=20;lim.attack.value=.003;lim.release.value=.15}this.mbus.connect(lim);lim.connect(c.destination);   // Limiter: Musik-Regler bis 200 % ohne Übersteuern
   this.apply();
   for(const n in this.src)this.decode(n);
   const mn=Object.keys(this.msrc).sort((a,b)=>(a===this.want?-1:0)-(b===this.want?-1:0));for(const n of mn)this.decodeMusic(n)}
  if(this.ctx.state==='suspended')this.ctx.resume()}
 decode(n){try{const b64=this.src[n].split(',')[1],bin=atob(b64),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
   const ok=b=>{this.buf[n]=b},bad=()=>{},p=this.ctx.decodeAudioData(u.buffer,ok,bad);if(p&&p.catch)p.catch(bad)}catch(e){}}
 apply(){const v=this.muted?0:this.vol;if(this.master)this.master.gain.value=v;if(this.mbus)this.mbus.gain.value=this.mmuted?0:v*this.mvol}
 // Musik getrennt von den Effekten: eigener Schalter + Regler (wirkt zusätzlich zur Gesamtlautstärke)
 setMusicVolume(v){this.mvol=Math.max(0,Math.min(2,v));this.apply()}
 setMusicMuted(m){this.mmuted=!!m;this.apply()}
 setVolume(v){this.vol=Math.max(0,Math.min(1,v));this.apply()}
 setMuted(m){this.muted=!!m;this.apply()}
 decodeMusic(n){try{const b64=this.msrc[n].split(',')[1],bin=atob(b64),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
   const ok=b=>{this.mbuf[n]=b;if(this.want===n)this.startMusic()},bad=()=>{},p=this.ctx.decodeAudioData(u.buffer,ok,bad);if(p&&p.catch)p.catch(bad)}catch(e){}}
 // Gewünschten Track setzen (null = keine Musik). Darf jederzeit aufgerufen werden (auch vor dem Unlock/Decode): läuft los, sobald Audio freigeschaltet und der Track dekodiert ist. Gleicher Track = keine Unterbrechung.
 music(name){this.want=name||null;this.startMusic()}
 startMusic(){const c=this.ctx,n=this.want;if(!c||!this.mbus||n===this.cur)return;if(n&&!this.mbuf[n])return;   // noch nicht dekodiert: alter Track läuft weiter
  const t=c.currentTime,old=this.node;
  if(old){try{old.g.gain.cancelScheduledValues(t);old.g.gain.setValueAtTime(old.g.gain.value,t);old.g.gain.linearRampToValueAtTime(0,t+FADE_OUT);old.s.stop(t+FADE_OUT+.05)}catch(e){}old.s.onended=()=>{try{old.g.disconnect()}catch(e){}}}
  this.node=null;this.cur=n;if(!n)return;
  const s=c.createBufferSource(),g=c.createGain();s.buffer=this.mbuf[n];s.loop=true;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(MUSIC_VOL[n]===undefined?.4:MUSIC_VOL[n],t+FADE_IN);s.connect(g);g.connect(this.mbus);s.start(t);this.node={s,g}}
 // Tab/Fenster nicht sichtbar: Audio anhalten statt im Hintergrund weiterzuspielen
 suspend(){if(this.ctx&&this.ctx.state==='running')this.ctx.suspend()}
 resume(){if(this.ctx&&this.ctx.state==='suspended')this.ctx.resume()}
 play(name,o){const c=this.ctx,b=this.buf[name];if(!c||!b||this.muted||this.vol<=0||c.state!=='running')return;
  const now=performance.now(),gap=GAP[name]||25;if(now-(this.last[name]===undefined?-1e9:this.last[name])<gap||this.voices>=28)return;this.last[name]=now;
  const vol=(o&&o.vol!==undefined)?o.vol:1,rate=(o&&o.rate)||1;
  const s=c.createBufferSource(),g=c.createGain();s.buffer=b;s.playbackRate.value=rate*(.96+Math.random()*.08);g.gain.value=vol;s.connect(g);g.connect(this.master);
  this.voices++;s.onended=()=>{this.voices--;g.disconnect()};s.start()}
}

// ===== render/fonts =====
// Schriften: Bebas Neue (Display/Banner), Orbitron (Logo/Tech), Rajdhani (UI-Text). Eingebettet als Data-URI (window.__FONTS__, vom Build),
// damit alles offline per Doppelklick läuft. Fehlt eine Schrift (z. B. Test/Headless), greifen die System-Fallbacks.
const CJK='"Yu Gothic","Hiragino Sans","Noto Sans CJK JP","Noto Sans JP","Microsoft YaHei","PingFang SC"';
const F_DISP=`"Bebas Neue",${CJK},Impact,"Arial Narrow",sans-serif`;
const F_TECH=`"Orbitron","Bebas Neue",${CJK},"Arial Black",sans-serif`;
const F_UI=`"Rajdhani","Segoe UI",${CJK},system-ui,sans-serif`;
function loadFonts(){
 const D=typeof window!=='undefined'&&window.__FONTS__,FF=typeof FontFace!=='undefined'?FontFace:null;
 if(!D||!FF||typeof document==='undefined'||!document.fonts||!document.fonts.add)return;
 const defs=[['Bebas Neue','bebas','100 900'],['Orbitron','orbitron-900','100 900'],['Rajdhani','rajdhani-500','100 600'],['Rajdhani','rajdhani-700','700 900']];
 for(const[fam,key,w]of defs){if(!D[key])continue;
  try{const f=new FF(fam,`url(${D[key]})`,{weight:w});f.load().then(x=>document.fonts.add(x)).catch(()=>{})}catch(e){}}}

// ===== render/fx =====


// Post-Processing + Ambient-Effekte (Canvas 2D, ohne Abhängigkeiten, läuft überall – auch ohne ctx.filter):
//  - Bloom (Downscale-Kette, Helligkeit quadriert = weiche Schwelle), Vignette (pulsiert bei niedrigem Leben), Filmkorn
//  - Chromatische Aberration bei Treffern/K.O./Hyper, Impact-Frame mit Speedlines bei harten Treffern
//  - schwebende Staubpartikel, Boden-Lichtpfützen unter den Kämpfern, Schadenszahlen
const fclamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const fmk=(w,h)=>{const c=document.createElement('canvas');c.width=Math.max(2,w|0);c.height=Math.max(2,h|0);return c};
const fhn=k=>{const s=Math.sin(k*12.9898)*43758.5453;return s-Math.floor(s)};
class PostFX{
 constructor(){this.a=null;this.b=null;this.c=null;this.tmp=null;this.noise=null;this.ok=typeof document!=='undefined';this.size=''}
 prep(cv){const k=cv.width+'x'+cv.height;if(k===this.size)return;this.size=k;const w=cv.width,h=cv.height;
  this.a=fmk(w/4,h/4);this.b=fmk(w/10,h/10);this.c=fmk(w/4,h/4);this.tmp=null;this.tr=null;this.tb=null}
 // Bloom: helle Bereiche (Neon, Funken, Treffer) strahlen weich aus
 bloom(g,cv,amt=.5){amt*=GFX.bloom;if(!this.ok||amt<=0)return;this.prep(cv);const w=cv.width,h=cv.height,a=this.a.getContext('2d'),c=this.c.getContext('2d'),b=this.b.getContext('2d');
  a.globalCompositeOperation='source-over';a.imageSmoothingEnabled=true;a.drawImage(cv,0,0,this.a.width,this.a.height);
  c.globalCompositeOperation='copy';c.drawImage(this.a,0,0);a.globalCompositeOperation='multiply';a.drawImage(this.c,0,0);a.globalCompositeOperation='source-over'; // Helligkeit² ≈ Schwellwert
  b.imageSmoothingEnabled=true;b.drawImage(this.a,0,0,this.b.width,this.b.height);
  g.save();g.setTransform(1,0,0,1,0,0);g.imageSmoothingEnabled=true;g.imageSmoothingQuality='high';g.globalCompositeOperation='lighter';
  g.globalAlpha=amt*.9;g.drawImage(this.b,0,0,w,h);g.globalAlpha=amt*.55;g.drawImage(this.a,0,0,w,h);g.restore()}
 // Chromatische Aberration: R/G/B-Kanäle werden gegeneinander verschoben (nur kurz bei Treffern -> kaum Kosten)
 aberr(g,cv,amt){if(!this.ok||!GFX.aberr||amt<.05)return;const w=cv.width,h=cv.height;
  if(!this.tmp||this.tmp.width!==w||this.tmp.height!==h){this.tmp=fmk(w,h);this.tr=fmk(w,h);this.tb=fmk(w,h)}
  const t=this.tmp.getContext('2d');t.globalCompositeOperation='copy';t.drawImage(cv,0,0);
  const ch=(cvs,col)=>{const x=cvs.getContext('2d');x.globalCompositeOperation='copy';x.drawImage(this.tmp,0,0);x.globalCompositeOperation='multiply';x.fillStyle=col;x.fillRect(0,0,w,h);x.globalCompositeOperation='source-over'};
  ch(this.tr,'#ff0000');ch(this.tb,'#0000ff');
  const d=Math.max(1,amt*w*.0065);
  g.save();g.setTransform(1,0,0,1,0,0);g.globalCompositeOperation='multiply';g.fillStyle='#00ff00';g.fillRect(0,0,w,h);   // Original -> nur Grün
  g.globalCompositeOperation='lighter';g.drawImage(this.tr,-d,0);g.drawImage(this.tb,d,0);g.restore()}
 vignette(g,cv,power=0,t=0){const w=cv.width,h=cv.height,k=.38+power*.25+(power>0?Math.sin(t*.2)*.04*power:0);
  g.save();g.setTransform(1,0,0,1,0,0);const v=g.createRadialGradient(w/2,h/2,h*.32,w/2,h/2,h*.98);v.addColorStop(0,'#0000');v.addColorStop(1,power>0?`rgba(${Math.round(90+120*power)},0,20,${fclamp(k+.2,0,.85)})`:`rgba(0,0,8,${k+.2})`);
  g.fillStyle=v;g.fillRect(0,0,w,h);g.restore()}
 grain(g,cv,a=.05){if(!this.ok||!GFX.grain)return;if(!this.noise){const n=fmk(160,160),x=n.getContext('2d');if(!x.createImageData)return;const d=x.createImageData(160,160);if(!d||!d.data)return;
   for(let i=0;i<d.data.length;i+=4){const v=Math.random()*255;d.data[i]=d.data[i+1]=d.data[i+2]=v;d.data[i+3]=255}x.putImageData(d,0,0);this.noise=n;this.np=null}
  if(!this.np)this.np=g.createPattern(this.noise,'repeat');if(!this.np)return;
  g.save();g.setTransform(1,0,0,1,0,0);g.globalAlpha=a;g.globalCompositeOperation='overlay';g.translate((Math.random()*160)|0,(Math.random()*160)|0);g.fillStyle=this.np;g.fillRect(-160,-160,cv.width+320,cv.height+320);g.restore()}
 // Schwebende Staub-/Funkenpartikel im Bildraum (Parallax-Tiefe), additiv
 dust(g,W,H,t,col='#bfa8ff',n=46,speed=1){n=Math.round(n*GFX.dust);if(n<=0)return;g.save();g.globalCompositeOperation='lighter';
  for(let i=0;i<n;i++){const z=.35+fhn(i*3.1)*.9,life=(t*speed*(8+z*16)+fhn(i)*H*3)%(H+40),x=(fhn(i*7.7)*W*1.2+Math.sin(t*.7*speed+i)*18*z)%(W+20),y=H+20-life;
   const a=(.15+.5*fhn(i*1.9+3))*Math.sin(fclamp(life/(H+40),0,1)*Math.PI);g.globalAlpha=a*.7;g.fillStyle=i%5?col:'#ffffff';g.beginPath();g.arc(x,y,.6+z*1.5,0,6.283);g.fill()}
  g.restore()}
 // Lichtstrahlen für Menü/Intro
 beams(g,W,H,t,col){if(GFX.level<1)return;g.save();g.globalCompositeOperation='lighter';
  for(let i=0;i<4;i++){const x=W*(.12+.25*i)+Math.sin(t*.35+i*1.7)*70,w=70+i*18,gr=g.createLinearGradient(0,0,0,H);gr.addColorStop(0,col+'00');gr.addColorStop(.5,col+'1c');gr.addColorStop(1,col+'00');
   g.fillStyle=gr;g.beginPath();g.moveTo(x-6,0);g.lineTo(x+6,0);g.lineTo(x+w+Math.sin(t*.5+i)*50,H);g.lineTo(x-w+Math.sin(t*.5+i)*50,H);g.fill()}g.restore()}
 // Lichtpfütze unter dem Kämpfer (Welt-Raum, innerhalb der Kamera): färbt den Boden in der Figurenfarbe
 floorGlow(g,f,ground,t,hit=0){if(!GFX.glow)return;const col=(f.char&&f.char.glow)||'#fff',sz=(f.char&&f.char.size)||1,air=fclamp((ground-f.y)/260,0,1),a=(.2+.12*Math.sin(t*3+f.x*.01)+hit*.35)*(1-air*.6),r=(95+hit*30)*sz;
  g.save();g.globalCompositeOperation='lighter';g.translate(f.x,ground+2);g.scale(1,.2);const gr=g.createRadialGradient(0,0,2,0,0,r);gr.addColorStop(0,col+Math.round(fclamp(a,0,1)*255).toString(16).padStart(2,'0'));gr.addColorStop(1,col+'00');
  g.fillStyle=gr;g.beginPath();g.arc(0,0,r,0,6.283);g.fill();g.restore()}
 // Impact-Frame bei harten Treffern/K.O.: Blitz + Speedlines aus dem Treffpunkt + kurze Abdunklung
 impact(g,game){const im=game.impact;if(!im||im.t<=0)return;const W=960,H=540,u=im.t/im.t0,[ox,oy]=game.camera.toScreen(im.x,im.y);
  g.save();if(u>.55){g.globalAlpha=(u-.55)/.45*.55*im.p;g.fillStyle='#fff';g.fillRect(0,0,W,H)}
  g.globalAlpha=.4*u*im.p;g.fillStyle='#000010';g.fillRect(0,0,W,H);
  g.globalCompositeOperation='lighter';g.strokeStyle=im.col;g.globalAlpha=.85*u*im.p;
  for(let i=0,N=Math.round(46*GFX.rays);i<N;i++){const a=fhn(i*5.3+im.seed)*6.283,r0=40+fhn(i)*90+(1-u)*70,r1=r0+90+fhn(i+9)*420;g.lineWidth=.8+fhn(i*2)*2.6*u;g.beginPath();g.moveTo(ox+Math.cos(a)*r0,oy+Math.sin(a)*r0*.8);g.lineTo(ox+Math.cos(a)*r1,oy+Math.sin(a)*r1*.8);g.stroke()}
  g.globalAlpha=.7*u*im.p;g.fillStyle='#fff';const r=26+(1-u)*70;g.beginPath();g.arc(ox,oy,r,0,6.283);g.fill();g.restore()}
 // Schadenszahlen / Textpops (Welt-Raum)
 pops(g,game){const z=game.camera.z||game.camera.zoom||1;g.save();g.lineJoin='round';g.textAlign='center';
  for(const p of game.pops){const u=p.age/p.life,e=1-Math.pow(1-fclamp(u*2.2,0,1),3),sc=(p.age<7?1.7-.7*(p.age/7):1)*p.size/z*.92,a=u>.65?1-(u-.65)/.35:1;
   g.save();g.translate(p.x+p.dx*e,p.y-46*e);g.scale(sc,sc);g.rotate(p.rot*(1-e*.6));g.globalAlpha=a;g.font=`${p.text?34:44}px ${p.tech?F_TECH:F_DISP}`;
   if('letterSpacing'in g)g.letterSpacing='1px';
   g.lineWidth=7;g.strokeStyle='#05020c';g.strokeText(p.s,0,0);const gr=g.createLinearGradient(0,-30,0,6);gr.addColorStop(0,'#ffffff');gr.addColorStop(1,p.col);g.fillStyle=gr;g.shadowColor=p.col;g.shadowBlur=14;g.fillText(p.s,0,0);g.restore()}
  g.restore()}
 // Alles Bildschirmweite auf die fertige Szene (vor dem HUD)
 scene(g,cv,game,t){const hp=Math.min(...game.fighters.map(f=>f.hp/f.maxHp)),low=game.phase==='fight'?fclamp((.28-hp)/.28,0,1):0;
  this.aberr(g,cv,game.aberr||0);this.bloom(g,cv,.5+(game.aberr||0)*.25);this.vignette(g,cv,low,t);this.grain(g,cv,.05)}
}

// ===== render/gl =====
// WebGL-Nachbearbeitung (läuft auf der GPU statt Canvas-2D): Bloom, chromatische Aberration, Vignette, Filmkorn in EINEM Durchgang.
// Die Szene wird weiter mit Canvas 2D in ein Offscreen-Canvas gezeichnet; dieses wird als Textur hochgeladen, hier veredelt und in einem
// eigenen Canvas (hinter dem HUD-Canvas) angezeigt. Schlägt irgendetwas fehl (kein WebGL, Kontextverlust), nutzt der Renderer den alten 2D-Pfad (fx.js).
const VS='attribute vec2 p;varying vec2 v;void main(){v=p*.5+.5;gl_Position=vec4(p,0.,1.);}';
const PRE='#ifdef GL_FRAGMENT_PRECISION_HIGH\nprecision highp float;\n#else\nprecision mediump float;\n#endif\n';
// Helligkeit² als weicher Schwellwert (wie im 2D-Pfad), 4 Taps beim Verkleinern gegen Flackern
const FS_BRIGHT=PRE+'uniform sampler2D t;uniform vec2 o;varying vec2 v;vec3 s(vec2 u){vec3 c=texture2D(t,u).rgb;return c*c;}void main(){gl_FragColor=vec4((s(v+vec2(-o.x,-o.y))+s(v+vec2(o.x,-o.y))+s(v+vec2(-o.x,o.y))+s(v+o))*.25,1.);}';
const FS_BLUR=PRE+'uniform sampler2D t;uniform vec2 d;varying vec2 v;void main(){vec3 a=vec3(0.);float ws=0.;for(int i=-4;i<=4;i++){float w=exp(-float(i*i)*.15);a+=texture2D(t,v+d*float(i)).rgb*w;ws+=w;}gl_FragColor=vec4(a/ws,1.);}';
const FS_MIX=PRE+'uniform sampler2D s,a,b;uniform float bl,ab,gr,tm,va;uniform vec3 vc;uniform vec2 asp;varying vec2 v;\n'
 +'float hs(vec2 p){return fract(sin(dot(p,vec2(12.9898,78.233)))*43758.5453);}\n'
 +'void main(){vec3 c;if(ab>0.){c=vec3(texture2D(s,v-vec2(ab,0.)).r,texture2D(s,v).g,texture2D(s,v+vec2(ab,0.)).b);}else c=texture2D(s,v).rgb;\n'
 +' if(bl>0.)c+=texture2D(b,v).rgb*bl*.9+texture2D(a,v).rgb*bl*.55;\n'
 +' float d=length((v-.5)*asp);c=mix(c,vc,clamp((d-.32)/.66,0.,1.)*va);\n'
 +' if(gr>0.){float n=hs(gl_FragCoord.xy+tm);vec3 ov=mix(2.*c*n,1.-2.*(1.-c)*(1.-n),step(.5,c));c=mix(c,ov,gr);}\n'
 +' gl_FragColor=vec4(c,1.);}';
class GLPost{
 constructor(){this.ok=false;this.w=0;this.h=0;try{this.init()}catch(e){this.ok=false}}
 init(){const cv=document.createElement('canvas');cv.width=cv.height=2;
  const gl=cv.getContext('webgl',{alpha:false,antialias:false,depth:false,stencil:false,preserveDrawingBuffer:false,powerPreference:'high-performance'});
  if(!gl||typeof gl.createShader!=='function')return;
  const prog=(fs,names)=>{const mk=(type,src)=>{const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw new Error('shader: '+gl.getShaderInfoLog(s));return s};
   const p=gl.createProgram();gl.attachShader(p,mk(gl.VERTEX_SHADER,VS));gl.attachShader(p,mk(gl.FRAGMENT_SHADER,fs));gl.bindAttribLocation(p,0,'p');gl.linkProgram(p);
   if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw new Error('link: '+gl.getProgramInfoLog(p));
   const u={};for(const n of names)u[n]=gl.getUniformLocation(p,n);return{p,u}};
  this.pb=prog(FS_BRIGHT,['t','o']);this.pl=prog(FS_BLUR,['t','d']);this.pm=prog(FS_MIX,['s','a','b','bl','ab','gr','tm','va','vc','asp']);
  const buf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buf);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);gl.enableVertexAttribArray(0);gl.vertexAttribPointer(0,2,gl.FLOAT,false,0,0);
  gl.disable(gl.DEPTH_TEST);gl.disable(gl.BLEND);
  cv.addEventListener('webglcontextlost',e=>{e.preventDefault();this.ok=false});
  this.cv=cv;this.gl=gl;this.ts=this.tex();this.ok=true}
 tex(){const gl=this.gl,t=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,t);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);return t}
 fbo(w,h){const gl=this.gl,t=this.tex();gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,w,h,0,gl.RGBA,gl.UNSIGNED_BYTE,null);
  const f=gl.createFramebuffer();gl.bindFramebuffer(gl.FRAMEBUFFER,f);gl.framebufferTexture2D(gl.FRAMEBUFFER,gl.COLOR_ATTACHMENT0,gl.TEXTURE_2D,t,0);return{t,f,w,h}}
 free(o){if(o){this.gl.deleteTexture(o.t);this.gl.deleteFramebuffer(o.f)}}
 size(w,h){const gl=this.gl;this.cv.width=w;this.cv.height=h;this.w=w;this.h=h;this.free(this.A);this.free(this.B1);this.free(this.B2);
  const q=Math.max(2,w>>2),qh=Math.max(2,h>>2),e=Math.max(2,w>>3),eh=Math.max(2,h>>3);
  this.A=this.fbo(q,qh);this.B1=this.fbo(e,eh);this.B2=this.fbo(e,eh);gl.bindFramebuffer(gl.FRAMEBUFFER,null)}
 bind(t,unit){const gl=this.gl;gl.activeTexture(gl.TEXTURE0+unit);gl.bindTexture(gl.TEXTURE_2D,t)}
 pass(P,target){const gl=this.gl;gl.bindFramebuffer(gl.FRAMEBUFFER,target?target.f:null);gl.viewport(0,0,target?target.w:this.w,target?target.h:this.h);gl.useProgram(P.p)}
 // src = Szenen-Canvas (2D). o = {bloom, ab (UV-Versatz), vc [r,g,b], va (Vignetten-Stärke), grain, t}
 render(src,o){const gl=this.gl,w=src.width,h=src.height;if(!this.ok)throw new Error('gl off');if(gl.isContextLost&&gl.isContextLost()){this.ok=false;throw new Error('lost')}
  if(w!==this.w||h!==this.h)this.size(w,h);
  this.bind(this.ts,0);gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,true);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,src);
  const bl=o.bloom>0?o.bloom:0;
  if(bl>0){
   this.pass(this.pb,this.A);gl.uniform1i(this.pb.u.t,0);gl.uniform2f(this.pb.u.o,1/w,1/h);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);                                  // hell, 1/4
   this.bind(this.A.t,0);this.pass(this.pl,this.B1);gl.uniform1i(this.pl.u.t,0);gl.uniform2f(this.pl.u.d,2/this.A.w,0);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);    // Weichzeichner waagerecht, 1/8
   this.bind(this.B1.t,0);this.pass(this.pl,this.B2);gl.uniform1i(this.pl.u.t,0);gl.uniform2f(this.pl.u.d,0,1/this.B1.h);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);   // senkrecht
   this.bind(this.ts,0);this.bind(this.A.t,1);this.bind(this.B2.t,2)}
  else{this.bind(this.ts,0);this.bind(this.ts,1);this.bind(this.ts,2)}
  this.pass(this.pm,null);const u=this.pm.u;gl.uniform1i(u.s,0);gl.uniform1i(u.a,1);gl.uniform1i(u.b,2);
  gl.uniform1f(u.bl,bl);gl.uniform1f(u.ab,o.ab||0);gl.uniform1f(u.gr,o.grain||0);gl.uniform1f(u.tm,((o.t||0)*7.13)%997);gl.uniform1f(u.va,o.va||0);
  gl.uniform3f(u.vc,o.vc[0],o.vc[1],o.vc[2]);gl.uniform2f(u.asp,w/h,1);gl.drawArrays(gl.TRIANGLE_STRIP,0,4)}
}

