 upper:{d:.6,k:[[0,ST1],[.14,S(.2,.05,.4,2.1,-.1,.6,-.9,.1,1,-.3,-4)],[.24,S(.05,-.1,.4,2.1,2.75,2.9,-.1,-.1,.15,.05,14,1)],[.38,S(.05,-.1,.4,2.1,2.75,2.9,-.1,-.1,.15,.05,14,1)],[.6,ST1]]},
