  const bg=g.createRadialGradient(W/2,floor,10,W/2,floor-60,230);bg.addColorStop(0,'#2a1a5e');bg.addColorStop(1,'#0a0618');g.fillStyle=bg;g.fillRect(0,0,W,H);
