  g.translate((game.kickX||0)+(game.shake>0?(Math.random()-.5)*game.shake*1.6:0),(game.kickY||0)+(game.shake>0?(Math.random()-.5)*game.shake*1.6:0));
  g.save();cam.apply(g);                                 // --- Welt: alles unter derselben Kamera-Matrix ---
